// Üretilen dosya: tool/ozgun/uret.py. Doğa · Ağaç türleri, orman kuşakları, tohum yayılma yolları ve bitki uyumları (iğne ve geniş yapraklılar, maki, garig, kurakçıl uyumlar, yaş halkaları) (zor).
const ozNature15Zor = <(String, String, List<String>, String)>[
  ('Olgunlaşan kozalakları ağaçtan bütün olarak yere düşmeyip dal üzerindeyken pullarını tek tek dağıtan ve geriye yalnızca dikey kozalak eksenini bırakan ibreli grup hangisidir?', 'Göknar ve sedir türleri', ['Kızılçam ve karaçam türleri', 'Doğu ladini ve mavi ladin', 'Mezarlık servisi ve mazı'], 'Abies (göknar) ve Cedrus (sedir) cinslerinde olgun kozalak pulları tohumlarla birlikte dalda dağılır, dal üzerinde yalnız sivri eksen çubuğu kalır.'),
  ('Ardıç ağaçlarının üzerinde görülen mavimsi-siyah veya kızılımsı küremsi yapılar botanik açıdan gerçek bir meyve olmayıp neyin başkalaşmasıyla oluşmuştur?', 'Etli hale gelerek birbiriyle kaynaşmış dişi kozalak pullarının', ['Çiçek tablasının şişerek tohum taslaklarını içine hapsetmesinin', 'Erkek polen keselerinin döllenme sonrasında sulu dokuya dönüşmesinin', 'Reçine kanallarının sürgün uçlarında küresel yumrular oluşturmasının'], 'Açık tohumlularda yumurtalık bulunmadığından gerçek meyve oluşmaz; ardıçtaki üzümsü yapı (galbulus) etli kozalak pullarının birleşmesidir.'),
  ('Kuzey Amerika\'nın kurak ve yüksek dağlık bölgelerinde yaşayan, beş bin yılı aşan yaşıyla bilinen en yaşlı klonal olmayan bireylere sahip çam türü hangisidir?', 'Bristlecone çamı (Pinus longaeva)', ['Ponderosa çamı (Pinus ponderosa)', 'Monteri çamı (Pinus radiata)', 'Weymouth çamı (Pinus strobus)'], 'Beyaz Dağlar\'da yetişen Pinus longaeva bireyleri (örneğin Methuselah) çok yavaş büyüyen yoğun reçineli odunları sayesinde 4800-5000 yıl yaşayabilmektedir.'),
  ('Sedir (Cedrus) ve melez (Larix) ağaçlarının dallarına yakından bakıldığında iğne yaprakların büyük bölümünün nasıl dizildiği görülür?', 'Kısa sürgünlerin ucunda yirmi ile kırk adetlik rozet veya püskül demetleri halinde', ['Her boğumda yalnızca ikişer adet ve tabanda zarsı kınla birleşmiş halde', 'Dalın iki yanına tarak dişleri gibi düzlemsel ve tek sıra halinde', 'Sürgünü tamamen gizleyen dört köşeli yatık pul yapraklar halinde'], 'Sedir ve melez ağaçlarında uzun sürgünlerde ibreler tek tek dizilirken, yanlardaki bodur kısa sürgünlerde çok sayıda ibre fırça veya rozet gibi küme yapar.'),
  ('Bir ormancının eline aldığı iğne yaprağın alt yüzünde iki adet belirgin beyaz stoma çizgisi görmesi ve yaprak ucunun batıcı olmayıp hafif kertikli olması öncelikle hangi cinse işaret eder?', 'Göknar (Abies)', ['Ladin (Picea)', 'Karaçam (Pinus)', 'Boylu ardıç (Juniperus)'], 'Göknar ibreleri yassıdır, uçları genellikle küt veya kertiklidir ve alt yüzlerinde mum tabakasıyla kaplı iki parlak beyaz stoma bandı bulunur.'),
  ('Dalından koparıldığında iğne yaprağın dal üzerinde küçük odunsu bir çıkıntı (yastıkçık) bırakarak törpü gibi pürüzlü bir sürgün yüzeyi oluşturması hangi ibreli cinse özgüdür?', 'Ladin (Picea)', ['Göknar (Abies)', 'Sedir (Cedrus)', 'Porsuk (Taxus)'], 'Ladin ibreleri sterigma adı verilen küçük odunsu çıkıntılar üzerinde oturur; ibre döküldüğünde dal yüzeyi pürüzlü kalır, oysa göknarda düz yuvarlak bir iz kalır.'),
  ('Çam ağaçlarında tozlaşmanın gerçekleşmesinden tohumların tamamen olgunlaşıp kozalaktan dökülmesine kadar geçen süre çoğu türde yaklaşık ne kadardır?', 'İki büyüme mevsimi', ['Yalnızca üç haftalık ilkbahar dönemi', 'Tozlaşmayı izleyen ilk kırk beş gün', 'On yılı aşan kesintisiz olgunlaşma evresi'], 'Çamlarda tozlaşma ilk ilkbaharda olur ancak polen tüpünün gelişimi çok yavaştır; gerçek döllenme ertesi ilkbaharda gerçekleşir ve kozalak ikinci sonbahar veya kışın olgunlaşır.'),
  ('İbreli ağaçların odun dokusu mikroskop altında incelendiğinde, kapalı tohumlu geniş yapraklı ağaçlardan farklı olarak hangi iletim elemanının bulunmadığı görülür?', 'Geniş çaplı trake borularının', ['Kenarlı geçitli trakeid hücrelerinin', 'Öz ışını parankiması dizilerinin', 'Vasküler kambiyum tabakasının'], 'Gnetales grubu hariç açık tohumluların ksilem dokusunda trake (vessel) bulunmaz; hem su iletimi hem mekanik destek kenarlı geçitli trakeidler tarafından sağlanır.'),
  ('Avustralya\'da 1994 yılında dar ve derin bir kanyonda yalnızca birkaç düzine bireyi canlı olarak keşfedilene dek yalnızca fosil kayıtlarından bilinen tarih öncesi ibreli ağaç hangisidir?', 'Wollemi çamı (Wollemia nobilis)', ['Norfolk çamı (Araucaria heterophylla)', 'Monterey servisi (Cupressus macrocarpa)', 'Kızıl ardıç (Juniperus oxycedrus)'], 'Araucariaceae familyasına ait Wollemi çamı, 150 milyon yıl öncesinden kalma fosillerle neredeyse aynı özelliklere sahip kritik tehlike altındaki bir relikt türdür.'),
  ('Kuzey Amerika\'nın güneydoğusundaki durgun su basar ormanlarda yaşayan ve oksijensiz çamurdan su yüzüne doğru \'diz\' adı verilen dikey solunum çıkıntıları uzatan ibreli ağaç hangisidir?', 'Bataklık servisi (Taxodium distichum)', ['Doğu beyaz çamı (Pinus strobus)', 'Kanada tsugası (Tsuga canadensis)', 'Kırmızı sedir (Juniperus virginiana)'], 'Bataklık servisi su altındaki köklerine havalandırma desteği sağlayan odunsu kök dizleriyle (pnömatofor benzeri çıkıntılar) ve kışın ibrelerini dökmesiyle tanınır.'),
  ('Kızılçam ile Halep çamı birbirine çok benzemesine karşın ormancılıkta kozalaklarının dala bağlanma biçimiyle nasıl ayırt edilir?', 'Kızılçam kozalakları sapsız veya çok kısa saplı olup dala dik-yatay otururken Halep çamı kozalakları kalın sapla geriye kıvrık sarkar', ['Kızılçam kozalakları dal ucunda yukarı doğru dik dururken Halep çamı kozalakları olgunlaşınca dağılır', 'Halep çamı kozalakları üzümsü ve mavimsi kabuklu iken kızılçam kozalakları ince kağıtsı pulludur', 'Kızılçam kozalakları yalnızca gövde kabuğu üzerinde çıkarken Halep çamı kozalakları kök sürgününde oluşur'], 'Kızılçamda kozalaklar neredeyse sapsızdır ve sürgüne dik açı yapar; Türkiye\'de Adana-Sarıçam ve Bodrum\'da lokal yayılan Halep çamında (Pinus halepensis) ise belirgin sapla geriye sarkar.'),
  ('Katran ardıcı (Juniperus oxycedrus) türünü boylu ardıç veya kokulu ardıçtan ilk bakışta ayıran yaprak özelliği aşağıdakilerden hangisidir?', 'Bütün yapraklarının batıcı iğne şeklinde olması ve üst yüzünde iki beyaz stoma çizgisi taşıması', ['Yapraklarının yalnızca kiremit dizilişli küt uçlu pullardan meydana gelmesi', 'Sonbaharda bütün ibrelerini bakır kırmızısına dönüştürerek tamamen dökmesi', 'İğne yapraklarının beşerli demetler halinde uzun zarsı kınlar içinden çıkması'], 'Ardıçların bir kısmı pul yapraklı iken katran ardıcı üçlü halkalar halinde dizilen sert batıcı iğne yapraklara ve üst yüzde iki beyaz çizgiye sahiptir; odunundan geleneksel ardıç katranı çıkarılır.'),
  ('Kıbrıs Adası\'nın Trodos Dağları\'nda sınırlı bir alanda yetişen ve diğer tüm gerçek sedir türlerine kıyasla çok daha kısa (0,5-1,2 cm) ibrelere sahip olan endemik sedir hangisidir?', 'Kıbrıs sediri (Cedrus brevifolia)', ['Atlas sediri (Cedrus atlantica)', 'Himalaya sediri (Cedrus deodara)', 'Lübnan sediri (Cedrus libani)'], 'Latince \'brevifolia\' (kısa yapraklı) epitetinden de anlaşılacağı üzere Kıbrıs sediri çok kısa ve mavimsi yeşil ibreleriyle karakteristiktir.'),
  ('Orta Çağ\'da meşhur İngiliz uzun yaylarının (longbow) yapımında hem basınca dayanıklı öz odunu hem de çekmeye esnek diri odunu bir arada sunduğu için tercih edilen ağaç hangisidir?', 'Adi porsuk (Taxus baccata)', ['Sarıçam (Pinus sylvestris)', 'Gümüşi göknar (Abies alba)', 'Melez ağacı (Larix decidua)'], 'Porsuk yayları ağaç gövdesinin diri ve öz odun sınırından kesilerek yapılırdı; dıştaki açık renkli diri odun yay gerildiğinde esnerken içteki koyu öz odun sıkışmaya direnç gösterirdi.'),
  ('Kanser tedavisinde hücre bölünmesini durdurucu kemoterapi ilacı olarak kullanılan \'paklitaksel\' (taksol) maddesi ilk kez hangi açık tohumlu ağacın kabuğundan izole edilmiştir?', 'Pasifik porsuğu (Taxus brevifolia)', ['Kaliforniya sekoyası (Sequoia sempervirens)', 'Mabet ağacı (Ginkgo biloba)', 'Toros sediri (Cedrus libani)'], 'Mikrotübülleri stabilize ederek mitozu durduran paklitaksel 1960\'larda Pasifik porsuğunun kabuğundan keşfedilmiş, daha sonra yarı sentetik olarak Avrupa porsuğu ibrelerinden üretilmiştir.'),
  ('Çin\'in iç kesimlerinde 1940\'lara kadar soyu tükenmiş sanılan, kışın yapraklarını tüysü sürgünleriyle birlikte döken \'su sekoyası\' (Metasequoia glyptostroboides) hangi özelliğiyle sahil sekoyasından ayrılır?', 'Sonbaharda sürgünleriyle beraber yaprak dökmesi ve yapraklarının dal üzerinde karşılıklı dizilmesi', ['Dört mevsim koyu yeşil sert dikenli ibreler taşıyıp kozalaklarını toprağın altında olgunlaştırması', 'Yalnızca kurak kireçtaşı kayalıklarında çalı formunda büyüyüp iki metreyi geçmemesi', 'Tohumlarını kırmızı etli arillus içinde tekli olarak geliştirip kuşlarla yayması'], 'Metasequoia (su sekoyası) kışın yaprak döken nadir ibrelilerden biridir; sahil sekoyasında yapraklar almaşık dizilirken su sekoyasında hem dallar hem yapraklar karşılıklı dizilir.'),
  ('Açık tohumlular şubesinde yer almasına rağmen görünüşte çöl çalısını andıran, eklemli yeşil gövdeleriyle fotosentez yapan ve \'efedrin\' alkaloidinin doğal kaynağı olan bitki cinsi hangisidir?', 'Denizüzümü (Ephedra)', ['Katran ardıcı (Juniperus)', 'Bodur dağ çamı (Pinus)', 'Kaya sarmaşığı (Hedera)'], 'Gnetophyta bölümüne ait Ephedra türleri Türkiye kurak yamaçlarında da yetişir; ksileminde trake bulundurmasıyla evrimsel olarak kapalı tohumlulara yaklaşan açık tohumlulardandır.'),
  ('Güneybatı Afrika\'daki Namib Çölü\'nde yaşayan, ömrü boyunca yalnızca iki adet kayış gibi uzayan dev yaprak üreten ve sis nemiyle bin yıldan fazla yaşayabilen sıra dışı açık tohumlu hangisidir?', 'Welwitschia mirabilis', ['Cycas revoluta', 'Araucaria columnaris', 'Podocarpus macrophyllus'], 'Gnetophyta üyesi Welwitschia mirabilis, kısa odunsu gövdesinden tabandan sürekli büyüyen ve uçlardan parçalanan yalnızca iki kalıcı yaprak çıkarmasıyla bitkiler âleminde tektir.'),
  ('Kanarya Adaları\'na özgü olan ve gövdesi tamamen yansa bile kabuk altındaki uyur tomurcuklardan yeniden sürgün verebilme yeteneğiyle çamlar arasında nadir bir istisna oluşturan tür hangisidir?', 'Kanarya çamı (Pinus canariensis)', ['Sarıçam (Pinus sylvestris)', 'Doğu beyaz çamı (Pinus strobus)', 'Avrupa karaçamı (Pinus nigra)'], 'Çamların büyük çoğunluğu tepe tacı yandığında ölür ve yalnızca tohumdan gençleşir; ancak Kanarya çamı kalın kabuğu altındaki epikormik tomurcuklardan yeniden yeşerebilir.'),
  ('Kuzey Amerika\'nın batı kıyılarında dev boyutlara ulaşan \'Douglas göknarı\' (Pseudotsuga menziesii) kozalaklarına bakıldığında diğer tüm ibrelilerden hangi belirgin detayla ayrılır?', 'Kozalak pullarının arasından dışarıya uzanan üç dişli çatal biçimli zarsı braktelerin bulunması', ['Kozalakların tamamen etli mor bir kabukla kaplı olup tek çekirdek içermesi', 'Kozalakların dal ucunda beşli yıldız şeklinde kaynaşarak odunlaşması', 'Olgunlaşan kozalakların parlak turuncu jelatinimsi bir sıvı salgılaması'], 'Yalancı tsuga (Pseudotsuga) kozalaklarında her odunsu pulun altından dışarı taşan üç uçlu brakte (fare kuyruğu ve arka ayaklarına benzetilir) kesin tanı özelliğidir.'),
  ('Açık tohumlu bitkilerin tohumlarında embriyoyu çevreleyen ve çimlenme sırasında besin sağlayan besi doku (endosperm) kromozom takımı açısından kapalı tohumlulardan nasıl ayrılır?', 'Döllenmeden önce dişi gametofitten geliştiği için haploit (n) kromozomlu olmasıyla', ['Çift döllenme sonucu polar çekirdeklerle birleştiği için triploit (3n) olmasıyla', 'Doğrudan ana ağacın kök parankimasından taşındığı için diploit (2n) olmasıyla', 'Polen kesesi duvarının kalınlaşmasıyla oluştuğu için tetraploit (4n) olmasıyla'], 'Açık tohumlularda çift döllenme görülmez; tohumdaki besleyici doku doğrudan haploit (n) megagametofit dokusudur, kapalı tohumlularda ise 3n endospermdir.'),
  ('Ginkgo biloba ve sikas (Cycas) türlerinin üreme biyolojisinde, çam ve göknar gibi diğer tüm açık tohumlulardan farklı olarak korunan ilkel ata özelliği hangisidir?', 'Polen tüpü içinde kamçılı ve hareketli spermatozoid hücreleri oluşturmaları', ['Sporla üreyerek yaprak altlarında kahverengi sorus keseleri geliştirmeleri', 'Tohum oluşturmadan doğrudan rüzgârla yayılan tek hücreli zigotlar bırakmaları', 'Böcekleri çekmek için renkli taç yapraklar ve şekerli nektar bezleri taşımaları'], 'Eğreltilerle tohumlu bitkiler arasındaki evrimsel geçişin kanıtı olarak Ginkgo ve Cycas\'ta polen tüpü besleyici emeç görevi görürken döllenmeyi çok kamçılı yüzen spermler gerçekleştirir.'),
  ('Yüksek rakımlı Alpler ve Karpatlar\'da yetişen, kozalakları olgunlaşsa bile açılmayan ve beşli ibre demetlerine sahip olan \'İsviçre fıstıkçamı\' (Pinus cembra) tohumlarını doğada başlıca hangi canlı yayar?', 'Köknar kargası (Nucifraga caryocatactes)', ['Dağ keçisi (Rupicapra rupicapra)', 'Kızıl orman karıncası (Formica rufa)', 'Bal arısı (Apis mellifera)'], 'Pinus cembra kozalakları ağaçta kapalı kalır; köknar kargası güçlü gagasıyla pulları kırıp kanatsız tohumları çıkarır ve kış için toprağa gömerek orman sınırının üstüne taşır.'),
  ('Doğu Karadeniz\'de ladin ormanlarında ağaçların kabuk altında galeriler açarak iletim demetlerini kesen ve kurumalara yol açan tehlikeli zararlı böcek hangisidir?', 'Dev kabuk böceği (Dendroctonus micans)', ['Zeytin sineği (Bactrocera oleae)', 'Süne böceği (Eurygaster integriceps)', 'Patates böceği (Leptinotarsa decemlineata)'], 'Dendroctonus micans ve Ips typographus gibi kabuk böcekleri ladin gövdelerinde floem tabakasını oyarak ağacın su-besin dengesini bozar; mücadelesinde Rhizophagus grandis yırtıcısı kullanılır.'),
  ('Sarıçam ve karaçam kozalaklarının pulları dıştan incelendiğinde pulun sırt kısmında yer alan eşkenar dörtgen biçimli şişkin kalkan bölgesine ne ad verilir?', 'Apofiz (kalkan) ve ortasındaki göbek', ['Karpel boyuncuğu ve tepecik', 'Perikarp kabuğu ve mezokarp', 'Kotiledon halkası ve hipokotil'], 'Çam kozalaklarının sınıflandırılmasında odunsu kozalak pulunun dışta görünen kabartılı ucu (apofiz) ve onun merkezindeki çıkıntı/diken (umbo) en önemli morfolojik kriterdir.'),
  ('Yeni Zelanda\'nın kuzey ormanlarına özgü olan, 50 metreyi aşan sütunsu gövdesiyle devasa boyutlara ulaşan ve reçinesi (kopal) değerli olan Güney Yarımküre ibrelisi hangisidir?', 'Kauri ağacı (Agathis australis)', ['Sahil çamı (Pinus pinaster)', 'Gümüşi göknar (Abies alba)', 'Kızıl servi (Chamaecyparis formosensis)'], 'Araucariaceae familyasından Kauri ağacı (örneğin ünlü Tane Mahuta bireyi), genişçe derimsi yapraklara sahip çok uzun ömürlü anıtsal bir açık tohumludur.'),
  ('Kuzey Amerika\'nın güneydoğusundaki yangın ekosistemlerine uyum sağlamış \'uzun yapraklı çam\' (Pinus palustris) fidelerinin ilk birkaç yıl gövde uzatmayıp yerde sık bir ot kümesi gibi kalmasına ne ad verilir?', 'Çim evresi (grass stage)', ['Kış uykusu (dormansi)', 'Yatık çalı (krummholz)', 'Hava kökü evresi'], 'Çim evresinde fide tüm enerjisini derin kazık köke yatırır; sık ve uzun ibre demeti tepe tomurcuğunu sık geçen düşük şiddetli yüzey yangınlarından korur, ardından hızla boya kalkar.'),
  ('Servi ve mazı gibi Servigiller (Cupressaceae) üyelerinde ilk yıl çimlenen fidede batıcı iğne yapraklar görülürken sonraki yıllarda sürgünlerin pul yapraklara dönüşmesine ne ad verilir?', 'Gençlik (juvenil) yaprak formundan ergin yaprak formuna geçiş', ['Klorofil kaybına bağlı mevsimsel yaprak başkalaşımı', 'Kuraklık stresine bağlı geçici yaprak dökümü', 'Mantar enfeksiyonu kaynaklı cadı süpürgesi oluşumu'], 'Cupressaceae türlerinde fideler atasal özellik olan iğne yapraklarla (juvenil form) başlar, bitki olgunlaştıkça sürgünü saran pul yapraklara (ergin form) geçer.'),
  ('Göknar ve çam ağaçlarının dallarında bazen kuş yuvasını andıran aşırı sık ve bodur sürgün kümelerinin (\'cadı süpürgesi\') oluşmasına ne yol açar?', 'Pas mantarları, fitoplazmalar veya parazitik ökseotlarının hormon dengesini bozarak yan tomurcukları aşırı uyarması', ['Sincapların kışlık kozalak saklamak için ince dalları birbirine düğümleyerek örmesi', 'Yıldırım düşmesi sonucunda tek bir daldaki kambiyumun iki kat hızlı bölünmesi', 'Ağacın rüzgâr yönündeki dallarını soğuktan korumak için kendi kendine sıklaştırması'], 'Örneğin göknarlarda Melampsorella caryophyllacearum pas mantarı sitokinin-oksin dengesini değiştirerek apikal dominansı kırar ve çalımsı cadı süpürgesi urları oluşturur.'),
  ('Güney Yarımküre\'nin ılıman yağmur ormanlarında yaygın olan ve çamlardan farklı olarak dar şeritsi veya mızraksı yassı yapraklar taşıyan büyük açık tohumlu ailesi hangisidir?', 'Podocarpaceae (Taşporsuğugiller)', ['Pinaceae (Çamgiller)', 'Taxodiaceae (Bataklıkservigiller)', 'Ephedraceae (Denizüzümügiller)'], 'Podocarpus türleri Güney Amerika, Afrika ve Avustralasya ormanlarında yaygındır; genişçe yaprakları ve tohum tabanındaki renkli etli reseptakulum (epimatium) ile kuşlarca yayılırlar.'),
  ('İbreli ormanların altındaki toprakların geniş yapraklı orman topraklarına kıyasla genellikle daha asidik (düşük pH\'lı) olmasının temel nedeni nedir?', 'Reçineli ve lignin oranı yüksek ibre döküntüsünün yavaş ayrışarak organik asitler üretmesi ve bazik katyonları yıkaması', ['İbreli ağaç köklerinin toprağa sürekli sülfürik asit ve nitrik asit pompalaması', 'Çam kozalaklarının çürürken topraktaki tüm silisyum kristallerini çözmesi', 'İbreli ormanlarda hiç yağmur yağmaması nedeniyle kalsiyum tuzlarının yüzeyde birikmesi'], 'İğne yaprak ölü örtüsü bazca fakir ve reçinelidir; serin-nemli iklimde mantarlarca yavaş parçalanırken fulvik ve hümik asitler oluşur, bu da podzollaşmaya ve asidik toprağa yol açar.'),
  ('Baklagiller familyasından olmamasına karşın kök yumrularında yaşayan \'Frankia\' adlı aktinomiset bakteriler sayesinde havadaki serbest azotu toprağa bağlayabilen dere boyu ağacı hangisidir?', 'Adi kızılağaç (Alnus glutinosa)', ['Ova akçaağacı (Acer campestre)', 'Adi dişbudak (Fraxinus excelsior)', 'Gümüşi ıhlamur (Tilia tomentosa)'], 'Doğu Karadeniz derelerinde ve bataklık kenarlarında yaygın olan kızılağaç, Frankia ortaklığıyla azotça fakir ıslak toprakları zenginleştirir ve odunu kesilince turuncu-kızıla döner.'),
  ('Kızılağaç türleri geniş yapraklı kapalı tohumlu ağaçlar olmalarına rağmen kış aylarında dallarında ibrelileri andıran küçük siyahımsı odunsu yapılar taşır; bu yapıların gerçek kimliği nedir?', 'Tohumlarını döktükten sonra dalda kalan odunlaşmış dişi çiçek kurulu', ['Böcek sokması sonucunda yaprak saplarında oluşan tanence zengin küresel mazılar', 'Havadaki nemi tutmak için yan tomurcukların etrafında gelişen mantar tabakaları', 'İlkbaharda polen yaymak üzere hazırlanmış reçine kaplı erkek spor keseleri'], 'Kızılağaçta dişi kedicik çiçek durumunun brakteleri olgunlaşınca odunlaşarak \'strobilus\' denen küçük kozalak benzeri yapıları oluşturur ve kış boyu dalda kalır.'),
  ('Ceviz ağaçlarının (Juglans regia) taç izdüşümü altındaki toprakta domates, yonca veya elma gibi birçok bitkinin cılız kalıp gelişememesine yol açan kimyasal etkileşim (allelopati) hangi maddeden kaynaklanır?', 'Yaprak, kök ve yeşil meyve kabuğundan toprağa yıkanan juglon bileşiğinden', ['Gövde kabuğundaki lentisellerden havaya salınan yoğun etilen gazından', 'Ceviz köklerinin topraktaki tüm demir ve magnezyumu kristalleştiren oksalik asidinden', 'Dökülen ceviz yapraklarının toprağın pH değerini bir gecede ikiye düşürmesinden'], 'Cevizdeki hidrojuglon yağmurla toprağa geçip oksitlendiğinde \'juglon\' adlı kinon bileşiğine dönüşür ve duyarlı komşu bitkilerde solunum ile kök gelişimini baskılar.'),
  ('Avrupa ve Kuzey Amerika\'daki yüz milyonlarca yaşlı karaağacın (Ulmus) 20. yüzyılda kuruyarak yok olmasına neden olan ünlü vasküler solgunluk hastalığının etmeni ve taşıyıcısı nedir?', 'Kabuk böcekleri aracılığıyla taşınan Ophiostoma cinsine ait patojen mantarlar', ['Rüzgârla yayılan ve yaprak kloroplastlarını parçalayan tütün mozaik virüsü', 'Toprak solucanlarıyla kökten giren ve öz odunu eriten anaerobik bakteriler', 'Göçmen kuşların gagasıyla aşılanan yarı parazitik ökseotu tohumları'], 'Hollanda karaağaç hastalığı (Dutch elm disease), Scolytus kabuk böceklerinin taşıdığı Ophiostoma ulmi / novo-ulmi mantarının ksilem borularını tıkamasıyla ağacı hızla kurutur.'),
  ('Sakarya Karasu Acarlar Longozu ve Kırklareli İğneada Longozu gibi su basar ormanlarımızın tabanında suya dayanıklılığı sayesinde en baskın üst tabaka ağacını oluşturan tür hangisidir?', 'Sivri meyveli dişbudak (Fraxinus angustifolia)', ['Toros sediri (Cedrus libani)', 'Tüylü meşe (Quercus pubescens)', 'Anadolu kestanesi (Castanea sativa)'], 'Longoz (subasar) ormanlarında yılın önemli bölümünde su altında kalan alüvyal topraklara dişbudak, kızılağaç, saplı meşe ve ova karaağacı uyum sağlamıştır; en baskını dişbudaktır.'),
  ('Dişbudak (Fraxinus) ile akçaağaç (Acer) kışın yapraksızken sürgün üzerindeki tomurcuk dizilişleri bakımından kayın, meşe ve çınardan nasıl ayrılır?', 'Tomurcukları ve dalları sürgün üzerinde karşılıklı çiftler halinde dizilirken diğerlerinde almaşık dizilir', ['Kış tomurcukları tamamen toprağın altındaki rizomlarda gizlenirken diğerlerinde dal ucunda durur', 'Sürgün uçlarında yalnızca beşli halkalar halinde dikenli tomurcuklar taşırken diğerleri tomurcuksuzdur', 'Tomurcuk pulları parlak mavi reçineyle kaplı iken kayın ve meşede çıplak yeşil yapraklıdır'], 'Geniş yapraklı ağaçların çoğunda yaprak ve tomurcuk dizilişi almaşık (alternatif) iken akçaağaç, dişbudak ve at kestanesinde karşılıklı (opozit) diziliş karakteristiktir; dişbudakta kış tomurcukları kadifemsi siyahtır.'),
  ('İncir ağacının (Ficus carica) etli olarak yediğimiz kısmı botanik açıdan tek bir meyve olmayıp içi boş armutsu bir çiçek tablasının iç duvarına dizilmiş yüzlerce küçük çiçekten oluşur. Bu özel yapıya ne ad verilir?', 'Sikonyum (yalancı bileşik meyve)', ['Samara (kanatlı fındıksı meyve)', 'Hesperidyum (dilimli narenciye meyvesi)', 'Silikva (iki gözlü kapsül meyve)'], 'İncirde çiçekler dışarıdan görünmez; sikonyum adı verilen kapalı etli reseptakulumun içindedir ve tozlaşması incir arıcığının (Blastophaga psenes) uçtaki delikten (ostiol) girmesiyle gerçekleşir.'),
  ('Doğu ve Güneydoğu Anadolu\'daki meşe ormanlarında mazı arısının (Cynips gallae-tinctoriae) genç sürgün tomurcuklarına yumurta bırakması sonucu oluşan küremsi \'meşe mazısı\' tarih boyunca hangi amaçla kullanılmıştır?', 'Yüksek gallik ve tannik asit içeriği sayesinde kalıcı siyah mürekkep yapımında ve dericilikte', ['Nişasta ve şeker deposu olarak kış aylarında un haline getirilip ekmek yapımında', 'İçindeki uçucu mentol kristalleri nedeniyle solunum açıcı buhar banyolarında', 'Esnek kauçuk lifleri barındırdığı için su geçirmez çadır dokumacılığında'], 'Mazı meşesi (Quercus infectoria) üzerindeki böcek galleri %50-70 oranında tanen içerir; demir sülfatla tepkimeye sokularak yüzyıllarca el yazmalarında kullanılan demir-mazı mürekkebi üretilmiştir.'),
  ('Avustralya okaliptüs ormanlarında yangınların neden çok hızlı tepe yangınına dönüştüğü ve buna rağmen okaliptüs ağaçlarının yangından birkaç hafta sonra nasıl yeniden yeşerdiği hangi ikiliyle açıklanır?', 'Yapraklarındaki uçucu sineol yağları yangını körüklerken kalın kabuk altındaki lignotuber ve epikormik tomurcuklar hemen sürgün verir', ['Köklerindeki su keseleri yangın anında patlayıp alevi söndürürken rüzgârla gelen sporlar külde çimlenir', 'Gövde odununda hiç selüloz bulunmadığı için yanmazken yan dallardaki kozalaklar ısıyla erir', 'Yangın dumanı okaliptüs yapraklarını taşlaştırarak korurken komşu ağaçların köklerinden su çeker'], 'Okaliptüsler pirofit (yangın sever) ağaçlardır; uçucu yağları rakip türleri yakan hızlı yangın çıkarır, kendileri ise kabuk altı uyur tomurcukları ve toprak altı şişkin gövde yumrusu (lignotuber) ile hızla canlanır.'),
  ('Hint Okyanusu\'ndaki Sokotra Adası\'na endemik olan, sık şemsiye biçimli tacı ve gövdesi kesildiğinde akan koyu kırmızı reçinesiyle dünyaca tanınan tek çenekli ağaçsı bitki hangisidir?', 'Ejderha kanı ağacı (Dracaena cinnabari)', ['Argan ağacı (Argania spinosa)', 'Demir ağacı (Parrotia persica)', 'Maun ağacı (Swietenia mahagoni)'], 'Sokotra\'nın kurak kireçtaşı platolarında yetişen Dracaena cinnabari, ters şemsiye tacıyla deniz sisini yoğuşturup kendi kök bölgesine damlatır ve kırmızı reçinesi vernik/boya olarak kullanılır.'),
  ('Sonbaharda kestane ağaçlarının gövde kabuğunda turuncu spor püstülleri oluşturarak kambiyumu öldüren ve Türkiye\'deki kestane ormanlarında büyük kurumalara yol açan karantina hastalığı hangisidir?', 'Kestane dal kanseri (Cryphonectria parasitica)', ['Meşe küllemesi (Erysiphe alphitoides)', 'Çınar yaprak yanıklığı (Apiognomonia veneta)', 'Zeytin dal kanseri (Pseudomonas savastanoi)'], 'Asya kökenli Cryphonectria parasitica mantarı kabuk yaralarından girerek iletim dokusunu kuşatır ve kanser yarasının üstündeki dal/gövdeyi kurutur; mücadelesinde hipovirülent suşlar kullanılır.'),
  ('Bir meşe ağacının sonbaharda kahverengileşip kuruyan yapraklarının bir kısmını kış boyunca hiç dökmeden dalları üzerinde tutması ve ancak ilkbaharda yeni tomurcuklar patlarken bırakması olayı nasıl adlandırılır?', 'Marsesens (kurumuş yaprakların kış boyu dalda alıkonulması)', ['Her dem yeşillik (yaprakların klorofilini koruyarak canlı kalması)', 'Gütasyon (yaprak kenarlarından sıvı su damlalarının atılması)', 'Vernalizasyon (çiçeklenme için kış soğuğunun algılanması)'], 'Genç meşe, kayın ve gürgen ağaçlarında yaprak sapı tabanındaki ayrılma (absisyon) tabakası sonbaharda tam gelişmez; dalda kalan kuru yapraklar kışın geyik/keçi gibi otçulların tomurcukları yemesini zorlaştırır.'),
  ('Amazon yağmur ormanlarında dev boyutlara ulaşan \'Brezilya cevizi\' (Bertholletia excelsa) ağaçlarından ticari plantasyonlarda verim alınamayıp ürünün hâlâ doğal ormandan toplanmasının ekolojik nedeni nedir?', 'Sert kapaklı çiçeklerini yalnızca doğal ormandaki orkidelerle ortak yaşayan iri Euglossine arılarının açıp tozlaştırabilmesi', ['Ağacın köklerinin yalnızca Amazon Nehri\'nin yılda bir kez getirdiği volkanik çamurda su emebilmesi', 'Tohumlarının çimlenmek için yalnızca jaguarların sindirim kanalındaki mide asidine ihtiyaç duyması', 'Plantasyonda yan yana dikildiğinde ağaçların birbirini zehirleyerek bir yıl içinde kurutması'], 'Brezilya cevizi, orkide kokusu toplayan iri arılara (tozlaşma için) ve taş gibi sert meyve kapsülünü (pyxidium) kemirip açabilen aguti kemirgenlerine (yayılma için) tam bağımlıdır.'),
  ('Dicle ve Fırat nehirlerinin tuzlu ve sıcak taşkın yataklarında doğal olarak yetişen; genç dallarında söğüt gibi dar şeritsi, üst dallarında ise kavak gibi geniş baklava biçimli yapraklar taşıyan tür hangisidir?', 'Fırat kavağı (Populus euphratica)', ['Titrek kavak (Populus tremula)', 'Salkım söğüt (Salix babylonica)', 'Kızılağaç (Alnus orientalis)'], 'Fırat kavağı aşırı sıcak, kuraklık ve toprak tuzluluğuna en dayanıklı kavak türü olup belirgin heterofili (aynı ağaçta söğütsü mızraksı ve geniş dişli yapraklar) gösterir.'),
  ('Tohumlu bitkilerin evrimsel tarihinde ilk ortaya çıkan kapalı tohumlu gruplardan biri kabul edilen, çanak ve taç yaprakları tam farklılaşmamış iri kokulu çiçeklerini kınkanatlı böceklerin tozlaştırdığı ağaç hangisidir?', 'Manolya (Magnolia grandiflora)', ['Salkım söğüt (Salix babylonica)', 'Ova akçaağacı (Acer campestre)', 'Adi dişbudak (Fraxinus excelsior)'], 'Bazal kapalı tohumlulardan olan manolyalar, arıların çeşitlenmesinden önce evrimleştiği için nektarsız fakat polence zengin çiçeklerini kınkanatlı böceklerin (Coleoptera) ezmesine dayanıklı sert karpellerle korur.'),
  ('Hazar Denizi\'nin güney kıyılarındaki Hirkan (Elburz) ormanlarına özgü olan, odunu suya batacak kadar yoğun olduğu için \'demir ağacı\' adıyla anılan ve gövdeleri birbirine doğal aşıyla kaynaşan tür hangisidir?', 'İran demir ağacı (Parrotia persica)', ['Kafkas gürgeni (Carpinus orientalis)', 'Doğu kayını (Fagus orientalis)', 'Doğu çınarı (Platanus orientalis)'], 'Cadıfındığıgiller (Hamamelidaceae) familyasından Parrotia persica, temas eden dallarının ve komşu gövdelerinin kabuk kaynaşması (inoskülasyon) yapmasıyla ve sonbahardaki alacalı renkleriyle ünlüdür.'),
  ('Dalları zarif biçimde toprağa ve su yüzeyine doğru sarktığı için gölet kıyılarında sıkça dikilen \'salkım söğüt\' (Salix babylonica) türünün doğal anavatanı neresidir?', 'Kuzey ve Orta Çin', ['Mezopotamya\'daki Fırat ve Dicle nehirlerinin aşağı deltası', 'Güney Amerika\'daki Amazon ve Orinoko nehir havzaları', 'İskandinavya yarımadasındaki buzul gölleri çevresi'], 'Bilimsel adındaki \'babylonica\' epiteti Linnaeus\'un yanılgısından kaynaklanır; tür gerçekte Çin kökenlidir ve tarihi İpek Yolu kervanlarıyla Batı Asya\'ya getirilmiştir.'),
  ('Türkiye\'nin Kuzeydoğu Anadolu ve Kafkasya sınırına yakın yüksek dağ ormanlarında 2400 metre rakıma kadar çıkabilen dayanıklı meşe türü aşağıdakilerden hangisidir?', 'İspir meşesi (Quercus macranthera subsp. syspirensis)', ['Palamut meşesi (Quercus ithaburensis)', 'Mantar meşesi (Quercus suber)', 'Kermes meşesi (Quercus coccifera)'], 'İspir meşesi soğuk ve karasal yüksek irtifa koşullarına en dayanıklı meşe taksonumuz olup Doğu Karadeniz ardı ile İç-Kuzeydoğu Anadolu geçişinde görülür.'),
  ('Doğu Karadeniz\'in yüksek yağışlı ılıman ormanlarında kayın ve ladinle birlikte yetişen, yaprakları kestaneye çok benzeyen ancak meyvesi üzümsü sert çekirdekli olan \'Gürgen yapraklı zelkovanın\' akrabası Kafkas relikti hangisidir?', 'Kafkas zelkovası (Zelkova carpinifolia)', ['Doğu çınarı (Platanus orientalis)', 'Gümüşi ıhlamur (Tilia tomentosa)', 'Adi iğde (Elaeagnus angustifolia)'], 'Karaağaçgillerden (Ulmaceae) Zelkova carpinifolia, Tersiyer döneminden kalma relikt bir tür olup Türkiye\'de Doğu Anadolu/Artvin-Hakkâri çevresinde çok sınırlı lokalitelerde bulunur.'),
  ('Çikolatanın hammaddesi olan kakao ağacında (Theobroma cacao) çiçeklerin ve kavun büyüklüğündeki bakla meyvelerin ince uç sürgünlerde değil, doğrudan ana gövde ve kalın yaşlı dallar üzerinde gelişmesine ne ad verilir?', 'Kauliflori (gövdede çiçeklenme)', ['Vivipari (ağaçta çimlenme)', 'Apomiksis (döllenmesiz tohum)', 'Epifitizm (dal üstü yaşam)'], 'Tropikal alt tabaka ağaçlarında sık görülen kauliflori hem ağır meyvelerin ince dalları kırmadan taşınmasını sağlar hem de gövdede dolaşan karınca/tatarcık ve yarasalarca tozlaşmayı kolaylaştırır.'),
  ('Geniş yapraklı ağaçların eğimli bir yamaçta veya tek yönlü rüzgâr altında kalan yan dallarının üst yüzeyinde sarkmayı önlemek üzere geliştirdiği selülozca zengin özel tepki odununa ne ad verilir?', 'Çekme odunu (tensiyon odunu)', ['Basınç odunu (kompresyon odunu)', 'İlkbahar iletim odunu', 'Yaralanma kallus dokusu'], 'Eğik dalları düzeltmek için kapalı tohumlu geniş yapraklılar dalın üst tarafında jelatinimsi selüloz lifli \'çekme odunu\' üretir; açık tohumlu ibreliler ise dalın alt tarafında ligninli \'basınç odunu\' oluşturur.'),
  ('Meşe ormanlarında \'ak meşeler\' (örneğin saplı meşe) ile \'kırmızı/siyah meşeler\' veya \'saçlı meşe\' (Quercus cerris) grupları arasında palamudun olgunlaşma süresi bakımından nasıl bir fark vardır?', 'Saplı ve sapsız meşede palamut bir yılda olgunlaşırken saçlı meşe ve palamut meşesinde iki yılda olgunlaşır', ['Tüm meşe türlerinde çiçeklenmeden on beş gün sonra olgun palamutlar toprağa dökülür', 'Ak meşelerde palamut toprağın altında oluşurken saçlı meşede yalnızca kök boğazında gelişir', 'Saçlı meşe yalnız dört yılda bir çiçek açıp aynı hafta içinde tohumlarını rüzgârla uçurur'], 'Quercus cinsinin Cerris ve Lobatae seksiyonlarındaki türlerde (örneğin saçlı meşe, kermes meşesi, palamut meşesi) çamlar gibi tozlaşmadan sonraki ikinci sonbaharda palamut olgunlaşır.'),
  ('Kuş dışkısıyla yüksek bir ağacın dal çatalına bırakılan tohumdan çimlenip aşağıya doğru hava kökleri sarkıtan, zamanla konak ağacın gövdesini kafes gibi sarıp ışıksız bırakarak öldüren yağmur ormanı bitkisi hangisidir?', 'Boğucu incir (Ficus aurea / Ficus watkinsiana)', ['Vanilya orkidesi (Vanilla planifolia)', 'Dev su zambağı (Victoria amazonica)', 'Küpe çiçeği (Fuchsia magellanica)'], 'Boğucu incirler hayata epifit olarak başlar; kökleri toprağa ulaştığında hızla kalınlaşıp birleşerek konak ağacın floem sıkışması ve gölgelenme sonucu çürümesine, ortası boş sütun kalmasına yol açar.'),
  ('Bazı bambu türlerinin aynı genetik soydan gelen dünyadaki tüm bireylerinin 60 ila 120 yılda bir aynı mevsimde hep birlikte çiçek açıp tohum verdikten sonra topluca kuruması hangi evrimsel avantajla açıklanır?', 'Kemirgen ve kuş popülasyonlarını doygunluğa ulaştırarak milyonlarca tohumun yenmeden çimlenmesini garantilemek', ['Topraktaki tüm suyu aynı anda tüketerek rakip çam ağaçlarının köklerini kurutmak', 'Atmosferdeki karbondioksit oranını bir haftada iki katına çıkararak ortamı ısıtmak', 'Polenlerin okyanus akıntılarıyla Antarktika kıyılarına taşınmasını sağlamak'], 'Senkronize kitlesel tohumlama (mast seeding / gregarious flowering), tohum avcılarının önceden çoğalmasını önler ve bir anda aşırı tohum sunarak avcı doygunluğu (predator satiation) yaratır.'),
  ('Maki formasyonu Akdeniz Havzası dışında benzer iklimin görüldüğü Kaliforniya, Orta Şili, Güney Afrika Kap Bölgesi ve Güneybatı Avustralya\'da farklı yerel adlarla anılır. Kaliforniya\'daki karşılığı hangisidir?', 'Çaparal (chaparral)', ['Tundra (tundra)', 'Savan (savanna)', 'Selva (selvas)'], 'Akdeniz tipi sklerofil çalılık biyomuna Akdeniz\'de maki, Kaliforniya\'da çaparal, Şili\'de matorral, Güney Afrika\'da fynbos ve Avustralya\'da mallee adı verilir.'),
  ('Türkiye\'de Avrupa-Sibirya fitocoğrafya bölgesinin en nemli ve ılıman doğu kesimini oluşturan, Artvin-Rize çevresinde çay ve kivi tarımına da olanak tanıyan tersiyer reliktlerince zengin alt bölüm nasıl adlandırılır?', 'Kolşik flora bölümü', ['Öksin batı bölümü', 'İran-Turan iç bölümü', 'Mezopotamya step bölümü'], 'Melet Irmağı\'ndan Kafkasya\'ya uzanan Doğu Karadeniz kesimi \'Kolşik\' kesimdir; yüksek yağış ve buzul çağından etkilenmeyen mikroiklimi sayesinde şimşir, porsuk, zelkova ve doğu ladini gibi türleri korumuştur.'),
  ('Yüksek dağ yamaçlarında yukarı doğru çıkıldıkça ağaç boylarının kısalıp sonunda ağaçların tamamen ortadan kalktığı \'doğal orman üst sınırını\' belirleyen en temel iklimsel faktör nedir?', 'En sıcak yaz ayındaki ortalama sıcaklığın odunsu doku ve sürgün olgunlaşması için yetersiz kalması', ['Yüksek rakımlarda yıllık toplam yağış miktarının her zaman sıfır milimetreye düşmesi', 'Dağ zirvelerinde atmosferdeki karbondioksit ve oksijen gazlarının tamamen tükenmesi', 'Yüksek irtifada güneşlenme süresinin alçak ovalara göre yarı yarıya azalması'], 'Orman üst sınırı (yaklaşık 10 °C Temmuz izotermi ile örtüşür) kış soğuğundan çok yaz sıcaklığının ve vejetasyon süresinin yeni odun-hücre duvarı sentezine yetmemesiyle çizilir.'),
  ('Aynı enlemde yer almalarına karşın Doğu Anadolu\'daki Süphan ve Ağrı çevresinde orman üst sınırının (yaklaşık 2600-2700 m) Karadeniz kıyısındaki dağlardan (yaklaşık 2000-2100 m) daha yüksekte olmasının nedeni nedir?', 'Karasallık ve yüksek plato etkisiyle Doğu Anadolu\'da yaz gündüz sıcaklıklarının aynı yükseltide daha yüksek olması', ['Doğu Anadolu\'da kış aylarında hiç kar yağmaması ve don olayının yaşanmaması', 'Karadeniz dağlarında toprağın tamamen volkanik kumlarla kaplı olup su tutmaması', 'Ağrı çevresinde okyanus akıntılarının sıcak ve nemli hava kütleleri taşıması'], 'Kütle yükseltisi (massenerhebung etkisi) ve karasallık nedeniyle iç bölgelerdeki yüksek platolarda yaz sıcaklıkları kıyıdaki bulutlu-serin dağlara göre daha yüksektir, bu da ağaç sınırını yukarı çeker.'),
  ('Tundra ile yüksek dağların orman sınırı üzerindeki \'alpin çayır\' biyomları görünüşte birbirine çok benzemesine rağmen alpin kuşağı arktik tundradan ayıran önemli çevresel fark nedir?', 'Alpin kuşakta gece-gündüz döngüsünün mevsimlik kesintiye uğramaması, dik yamaçlar nedeniyle iyi drenaj ve yüksek UV ışınımı', ['Alpin çayırların yılın on iki ayı boyunca otuz derece sıcaklıkta ve tamamen kurak kalması', 'Arktik tundrada atmosfer basıncının sıfır olması ve hiç rüzgâr esmemesi', 'Alpin kuşakta yalnızca kırk metre boyundaki dev ibreli ağaçların yetişebilmesi'], 'Orta ve alçak enlem dağlarındaki alpin çayırlar kutuplardaki gibi aylarca süren kış karanlığı ve yaygın düz permafrost yaşamaz; buna karşın ince atmosfer nedeniyle şiddetli morötesi (UV) ışınıma maruz kalır.'),
  ('Güney Afrika\'nın en güneybatı ucundaki Kap (Cape) Floristik Bölgesi\'nde görülen, protea ve funda (Erica) türlerince son derece zengin, düzenli çalı yangınlarına bağımlı Akdeniz tipi bitki örtüsüne ne ad verilir?', 'Fynbos', ['Pampa', 'Tayga', 'Caatinga'], 'Fynbos bitki örtüsü dar bir alanda 9000\'e yakın bitki türü (%70\'i endemik) barındırır; birçok türün tohumları duman içindeki \'karrikin\' kimyasallarını algılayınca çimlenir.'),
  ('Amanos (Nur) Dağları\'nın Akdeniz iklim kuşağının ortasında yer almasına rağmen kayın, gürgen, porsuk ve ıhlamur gibi Karadeniz (Öksin) kökenli nemcil ağaç topluluklarına ev sahipliği yapmasının nedeni nedir?', 'İskenderun Körfezi\'nden yükselen nemli denizel hava kütlelerinin dik yamaçlarda bol orografik yağış ve yaz sisi bırakması', ['Bölgeye yirminci yüzyılda uçaklarla Karadeniz\'den milyonlarca ton kayın tohumu atılmış olması', 'Amanos Dağları\'nın altında sıcak su gayzerlerinin kış boyu toprağı alttan ısıtması', 'Suriye Çölü\'nden esen kuru samyeli rüzgârlarının kayın yapraklarını sertleştirmesi'], 'Amanos Dağları buzul ve buzul sonrası dönemlerde denizden gelen nemli rüzgârları dik kesen konumu sayesinde Karadeniz kökenli nemcil türler için güneydeki en önemli relikt sığınak (enklav) olmuştur.'),
  ('Benzer biçimde Tokat-Erbaa ve Niksar (Kelkit Vadisi) ile Çoruh Vadisi\'nin kuytu tabanlarında Karadeniz Bölgesi sınırları içinde olmalarına karşın zeytin, kızılçam, kermes meşesi ve sandal ağacı görülmesi neyin sonucudur?', 'Derin çöküntü vadilerinde fön etkisi ve yağış gölgesiyle Akdeniz iklimine benzer ılıman-kurak mikroklima oluşmasının', ['Bu vadilerdeki akarsuların Akdeniz\'den ters yönde kuzeye doğru tuzlu su taşımasının', 'Bölgedeki toprakların tamamen kireçsiz bataklık turbasından meydana gelmesinin', 'Yüksek dağ zirvelerinin güneş ışığını vadilere hiç sokmayarak sürekli don yaratmasının'], 'Kelkit, Gökırmak ve Çoruh gibi oluk vadiler kuzey rüzgârlarına kapalı kaldığından kışları ılık Akdeniz enklavları oluşur ve maki-kızılçam elemanları buralarda varlığını sürdürür.'),
  ('Brezilya\'nın kuzeydoğusundaki yarı kurak iç bölgede yayılan; kaktüsler, dikenli baklagiller ve kurak mevsimde bembeyaz çıplak gövdeleriyle kalan yaprak döken ağaçlardan oluşan (\'beyaz orman\') biyom hangisidir?', 'Caatinga', ['Pantanal', 'Tundra', 'Kolşik orman'], 'Tupi dilinde \'beyaz orman\' anlamına gelen Caatinga, yılın 7-8 ayı kurak geçen Kuzeydoğu Brezilya\'ya özgü dikenli-kserofitik kuru orman ve çalı biyomudur.'),
  ('Güney Yarımküre\'nin serin ılıman ormanlarında (Şili-Arjantin Patagonya, Yeni Zelanda ve Tazmanya) Kuzey Yarımküre\'deki kayınların ekolojik karşılığı olan \'Güney kayını\' (Nothofagus) cinsinin bu birbirinden uzak kara parçalarında ortak bulunması neyin kanıtıdır?', 'Bu kara kütlelerinin geçmişte Gondvana süperkıtasının birbirine bağlı parçaları olduğunun', ['Nothofagus tohumlarının stratosfer rüzgârlarıyla uzay sınırından kıtalar arası uçtuğunun', 'Balinaların Güney Okyanusu\'nda bu ağaçların tohumlarını yutarak kıyılara taşıdığının', 'Modern gemilerin balast sularıyla bu ormanları son yüzyılda kurduğunun'], 'Tuzlu suya dayanamayan ve uzak mesafeye uçamayan tohumlara sahip Nothofagus cinsinin Güney Amerika, Avustralasya ve Antarktika fosillerindeki yayılışı, levha tektoniği ve Gondvana birliğinin klasik biyocoğrafik kanıtıdır.'),
  ('Boreal ormanların ve asidik bataklıkların zeminini halı gibi kaplayan, kendi kuru ağırlığının 20 katına kadar su tutabilen ve havasız ortamda birikerek \'turba (torf)\' oluşumunu sağlayan çiçeksiz bitki hangisidir?', 'Turba yosunu (Sphagnum)', ['At kuyruğu (Equisetum)', 'Kartal eğreltisi (Pteridium)', 'Sakal likeni (Usnea)'], 'Sphagnum kara yosunları ölü hiyalin hücrelerinde dev miktarda su tutar ve ortama hidrojen iyonu vererek suyu asitleştirir; çürüme durduğu için binlerce yılda kalın turba yatakları birikir.'),
  ('Avustralya\'nın yarı kurak iç bölgelerinde okaliptüs cinsinin çalımsı türlerinin toprak altındaki şişkin odunsu yumrudan (lignotuber) çok sayıda ince gövde çıkararak oluşturduğu maki benzeri bitki örtüsüne ne ad verilir?', 'Mallee çalılığı', ['Páramo yüksek çayırı', 'Mangrov gelgit ormanı', 'Öksin kayın kuşağı'], 'Güney ve Batı Avustralya\'nın Akdeniz ikliminden çöle geçiş kuşağında yer alan \'Mallee\', çok gövdeli bodur okaliptüslerin kurduğu yangına dayanıklı özgün bir sklerofil formasyondur.'),
  ('And Dağları\'nın ekvatoral kesiminde (Kolombiya, Ekvador, Venezuela) orman üst sınırı ile kalıcı kar sınırı arasındaki 3200-4500 metrelerde yer alan, sisli-soğuk iklimde dev rozetli \'frailejón\' (Espeletia) bitkilerinin yükseldiği tropikal alpin biyom hangisidir?', 'Páramo', ['Cerrado', 'Çaparal', 'Step'], 'Páramo ekosisteminde \'her gün yaz, her gece kış\' yaşanır; dev rozet bitkileri (Espeletia) gövdelerini ölü tüylü yaprak kılıflarıyla sararak gece donlarından iç su borularını korur.'),
  ('Anadolu\'da maki kuşağının karakteristik elemanlarından olan \'mersin\' (Myrtus communis) çalısının yaprakları ışığa tutulduğunda toplu iğne ucu gibi saydam noktalar görülmesinin anatomik nedeni nedir?', 'Yaprak mezofil dokusu içinde uçucu yağ depolayan şizogen salgı ceplerinin bulunması', ['Yaprak bitlerinin beslenirken dokuda mikroskobik hava pencereleri açmış olması', 'Stoma bekçi hücrelerinin kireç kristalleriyle dolup mercek gibi parlaması', 'İletim demetlerinin klorofilsiz sklerankima halkalarıyla dışarıya açılması'], 'Mersin, sarı kantaron ve turunçgil yaprakları ışığa tutulduğunda görülen saydam noktacıklar, uçucu yağ (mersinde mirtol ve sineol) dolu iç salgı bezleridir.'),
  ('Karadeniz dağlarındaki ormanların üst sınırında veya rüzgârlı sırtlarda kayın, ardıç ve ormangüllerinin rüzgâr ve kalın kar örtüsü altında boylanamayıp eğri büğrü, yere yatık bodur çalılıklar oluşturmasına ne ad verilir?', 'Krummholz (eğri odun / cüce orman kuşağı)', ['Longoz (alüvyal subasar orman)', 'Epifitik kanopi bahçesi', 'Halofitik tuz tavası'], 'Almanca \'eğri odun\' anlamına gelen krummholz kuşağında ağaçlar genetik değil ekolojik baskı (kar yüksekliğinin üstüne çıkan sürgünlerin donup kuruması) nedeniyle halı gibi yatık büyür.'),
  ('Geniş yapraklı ağaçlarda öz odun oluşumu sırasında komşu parankima hücrelerinin geçitlerden trake borularının içine doğru balon gibi şişerek su yolunu fiziksel olarak tıkamasına ne ad verilir?', 'Tilozis (tikaç) oluşumu', ['Kambiyal farklılaşma halkası gelişimi', 'Kenarlı geçit torus zarının erimesi', 'Periderm mantarlaşma tabakası birikimi'], 'Tilozisler hem doğal öz odunlaşma sürecinde hem de yaralanma ve vasküler mantar saldırılarında ksilem borularını tıkayarak patojenlerin gövde boyunca yayılmasını sınırlar.'),
  ('Ahşap teknolojisinde meşe, kestane ve dişbudak gibi ağaçların yıllık halkalarının başlangıcında çıplak gözle bile seçilebilen iri gözenek sıraları bulunması hangi odun anatomisi terimiyle ifade edilir?', 'Halkalı traheli odun', ['Dağınık parankimalı homojen odun', 'Trakesiz reçine kanallı yumuşak odun', 'İnterkalar meristemli lifsi odun'], 'İlkbahar odunundaki trake çapları yaz odunundakilerden çok büyük olup belirgin bir halka oluşturuyorsa buna halkalı traheli (ring-porous) odun denir.'),
  ('Kayın, akçaağaç, huş ve kavak gibi ağaçların enine kesitinde ilkbahar ve yaz odunu içindeki trake borularının neredeyse eşit çapta olup halka boyunca homojen dağılması nasıl adlandırılır?', 'Dağınık traheli odun', ['Merkezi tilozisli halkalı odun', 'Kenarlı trakeidli açık tohumlu odunu', 'Çift kambiyumlu anormal sekonder odun'], 'Dağınık traheli (diffuse-porous) ağaçlarda trake çapları mevsim boyunca pek değişmez; bu nedenle odun dokusu daha tekdüze ve ince gözenekli görünür.'),
  ('Kayın ağacının 150 yaşına gelse bile fil derisi gibi düz ve çatlamamış bir kabuk taşıması, buna karşılık meşe ve karaçamın derin yarıklarla parçalanmış kaba bir dış kabuk (\'ritidom\') oluşturması neyle açıklanır?', 'Kayında ilk mantar kambiyumu genişleyerek sürerken meşede derinde yeni peridermler kurulur', ['Kayın ağacının gövdesinin enine hiç kalınlaşmayıp yalnız boyuna uzaması, meşenin ise yalnızca enine büyümesiyle açıklanır', 'Meşe kabuğundaki hücrelerin güneş ışığında erimesi, kayın kabuğunun ise silisyum biriktirerek taşlaşmasıyla gerçekleşir', 'Kayının her sonbaharda tüm dış kabuğunu yapraklarıyla birlikte döküp ilkbaharda sıfırdan yeşil kabuk üretmesiyle oluşur'], 'Kayında tek bir yüzeysel periderm gövde kalınlaştıkça teğetsel bölünmelerle esner; çoğu ağaçta ise iç floemde ardışık yeni peridermler oluşur ve dışta kalan ölü dokular çatlayarak ritidomu (dış kabuk) meydana getirir.'),
  ('Ağaç biyolojisinde Alex Shigo tarafından geliştirilen \'CODIT\' (Ağaçlarda Çürümenin Bölmelendirilmesi) modeline göre yaralanan bir ağaç çürükçül mantarlara karşı nasıl tepki verir?', 'Hasarlı dokuyu onarmaz; çevresine kimyasal ve anatomik duvarlar örerek çürüğü hapseder', ['Çürüyen odun hücrelerini fagositozla eritip yerlerine taze bölünen sağlıklı trake boruları yerleştirir', 'Yaralı bölgedeki tüm öz odunu sıvılaştırarak kabuk çatlaklarından dışarıya reçine gibi akıtır', 'Mantar hiflerini kök uçlarına kadar indirip toprağa bırakarak gövdeyi tamamen steril hale getirir'], 'Hayvan dokularının aksine ağaçlar ölü veya yaralı ksilem hücrelerini yenileyemez; bunun yerine iletim borularını tıkayıp fenolik bariyerler ve yeni bir \'bariyer zonu\' (4. duvar) örerek çürüğü sınırlar.'),
  ('Bir ağaç dalı gövdeden çok uzakta güdük bırakılarak ya da gövdeye sıfır yanaşıp \'dal yakası\' (branch collar) kesilerek budandığında neden ciddi gövde çürüklüğü riski doğar?', 'Savunma bariyerini taşıyan dal yakası zedelenirse çürük ana gövdeye yürür', ['Dal yakası kesildiğinde ağacın tüm yapraklarındaki klorofil bir hafta içinde parçalanarak sonbahar dökümü başlar', 'Uzun bırakılan dal güdüğü toprağa doğru kök salarak ana ağacın suyunu tüketen parazit bir gövdeye dönüşür', 'Doğru budama yapılmadığında vasküler kambiyum yön değiştirerek odun dokusunu kabuğun dış yüzeyinde üretir'], 'Dalın gövdeyle birleştiği şişkin dal yakası (branch collar) CODIT savunma duvarlarının merkezidir; yaka korunarak hemen dışından kesildiğinde ağaç yarayı hızla kapatır.'),
  ('Dik bir yamaçta toprak kayması veya rüzgâr etkisiyle eğilen bir çam (açık tohumlu) ağacı, gövdesini yeniden dikey konuma itebilmek için eğimin hangi tarafında ne tür bir \'reaksiyon odunu\' üretir?', 'Eğik gövdenin alt tarafında ligninli basınç odunu üretir', ['Eğik gövdenin üst tarafında selülozca zengin jelatinimsi çekme odunu üretir', 'Gövdenin yalnız kuzeye bakan yüzünde süngerimsi boşluklu mantar odunu üretir', 'Tüm yaş halkasını eşit kalınlıkta daraltarak gövdeyi yere paralel sabitleyen lifler üretir'], 'İbreli ağaçlar eğilen gövde veya dalın alt kısmında hücre duvarları aşırı ligninleşmiş geniş halkalı \'basınç odunu\' (compression wood) oluşturarak gövdeyi alttan yukarı doğru iter.'),
  ('Aynı eğilme stresine maruz kalan kayın, kavak veya meşe gibi geniş yapraklı (kapalı tohumlu) bir ağaç ise gövdesini doğrultmak için hangi mekanik stratejiyi uygular?', 'Eğik gövdenin üst tarafında selülozlu çekme odunu üreterek çeker', ['Eğik gövdenin alt tarafında reçine kanallarıyla dolu koyu kırmızı basınç odunu üreterek iter', 'Eğilen yöndeki tüm köklerini koparıp karşı tarafta hava kökleriyle gövdeyi askıya alır', 'Üst taraftaki kambiyum bölünmesini tamamen durdurup yalnız kabuk kalınlığını on katına çıkarır'], 'Kapalı tohumlu ağaçlarda reaksiyon odunu eğimin üst yüzünde oluşur; \'çekme odunu\' (tension wood) içindeki jelatinimsi lifler büzülerek halat gibi gövdeyi yukarı doğru çeker.'),
  ('Bir ağacın gövde kesitinde tek bir takvim yılı içinde normal yıllık halkanın ortasında ince koyu bir bant belirerek iki yıl geçmiş gibi \'yalancı halka\' (false ring) oluşmasına ne yol açabilir?', 'Yaz ortası geçici kuraklık veya dondan sonra yağışla büyümenin tekrar hızlanması', ['Ağacın aynı yıl içinde hem ilkbaharda hem kış ortasında iki kez çiçek açıp iki kez tohum olgunlaştırması', 'Topraktaki mikoriza mantarlarının yaz ortasında köklerden çekilip sonbaharda başka bir türle yer değiştirmesi', 'Güneş lekelerinin on bir yıllık döngüsü sırasında morötesi ışınların kabuk altındaki kambiyumu ikiye bölmesi'], 'Yaz ortası kuraklığı, dolu veya böcek yaprak yenimi kambiyumu geçici olarak kalın çeperli dar hücre üretmeye zorlar; koşullar düzelince tekrar geniş hücreler üretilir ve kesitte çift halka izlenimi doğar.'),
  ('Hint Okyanusu\'ndaki Sokotra Adası\'nın kurak platolarına özgü olan, şemsiye biçimli sık tepesiyle sisi yoğuşturan ve yaralandığında koyu kırmızı reçine akıtan monokotil ağaç hangisidir?', 'Sokotra ejderha kanı ağacı', ['Madagaskar yelpaze biçimli gezgin palmiyesi', 'Doğu Afrika savan kuşağı dev baobab ağacı', 'Güney Arabistan kurak yamaç mür reçine ağacı'], 'Kuşkonmazgillerden (Asparagaceae) Dracaena cinnabari, tek çenekli olmasına rağmen özel bir monokotil kambiyumuyla kalınlaşır ve keman verniği ile halk tıbbında kullanılan \'ejderha kanı\' reçinesini verir.'),
  ('Ağacın yakında dökeceği sonbahar yapraklarında enerji harcayarak yeniden kırmızı antosiyanin pigmenti üretmesinin bitki fizyolojisindeki \'fotokoruma hipotezine\' göre yararı nedir?', 'Aşırı ışığı perdeleyerek azot ve fosforun sürgüne geri taşınmasını korumak', ['Kırmızı renkle arıları ve kelebekleri sonbahar sonunda yapraklara çekerek geç tozlaşma yaptırmak', 'Güneşin kızılötesi ışınlarını yansıtarak ağacın kök sistemini kış boyunca sıfır derecenin altında tutmak', 'Dökülen yaprakların toprakta hiç çürümeden taşlaşarak yabancı otların çıkışını engellemesini sağlamak'], 'Soğuk ve parlak sonbahar günlerinde klorofili azalan yaprak foto-oksidatif hasara açıktır; antosiyanin güneş kalkanı görevi görerek yapraktaki amino asit ve minerallerin gövdeye geri emilimine zaman kazandırır.'),
  ('Yaprak dökümü (absisyon) sürecinde yaprak sapının dala bağlandığı taban kısmındaki \'ayrılma bölgesi\' hücrelerinde hangi hormonal değişim kopmayı tetikler?', 'Oksin akışının azalmasıyla ayrılma bölgesinin etilene duyarlılaşması', ['Sitokinin ve giberellin hormonlarının yaprak sapında on kat artarak hücre duvarlarını odunlaştırması', 'Köklerden gelen absisik asidin yaprak ayasını şişirerek sapı mekanik basınçla patlatması', 'Etilen gazının tamamen tükenmesi üzerine oksinin selüloz liflerini dondurarak kırması'], 'Sağlıklı yeşil yaprak sürekli oksin üreterek absisyonu engeller; sonbaharda oksin azalınca etilen pektinaz ve selülaz enzimlerini uyararak ayrılma tabakası hücrelerinin orta lamellerini çözer.'),
  ('Meşe, gürgen ve genç kayın ağaçlarının kuruyup kahverengiye dönmüş ölü yapraklarını sonbaharda dökmeyip kış boyunca ve hatta ilkbaharda yeni tomurcuklar patlayana dek dalda tutmasına ne ad verilir?', 'Marsesens olayı', ['Her dem yeşil sklerofil yaprak uyumu', 'Kışlık vernalizasyon soğuklama tepkisi', 'Kabuk altı epikormik sürgünlenme durumu'], 'Özellikle ağaçların alt dallarında ve genç bireylerde ayrılma tabakasının tam gelişmemesiyle görülen marsesens, kışın geyik gibi otçulları kuru yapraklarla caydırmaya ve ilkbaharda toprağa taze malç sağlamaya yardımcı olur.'),
  ('Balsa ağacının tam tersine, yoğunluğu suyun yoğunluğundan çok yüksek (~1,25-1,35 g/cm³) olduğu için suya atıldığında taş gibi batan ve doğal yağlı reçinesi sayesinde gemi pervane şaft yataklarında kullanılmış ağaç hangisidir?', 'Peygamber ağacı', ['Avrasya nehir boyu gümüşi kavak ağacı', 'Sarkık dallı salkım söğüt ağacı türü', 'Doğu Asya hızlı büyüyen kral pavlonya ağacı'], 'Karayipler kökenli Guaiacum officinale (\'yaşam odunu\'), Janka sertlik ölçeğinin zirvesindeki türlerdendir; kendi kendini yağlayan reçineli ve kenetlenmiş lifli odunu metal rulmanlar kadar dayanıklıdır.'),
  ('Şeker akçaağacında (Acer saccharum) ise öz suyu akışının yalnızca kök basıncıyla değil, geceleri sıfırın altına düşen ve gündüzleri sıfırın üzerine çıkan sıcaklıklarda gövdede gerçekleşmesi hangi fiziksel mekanizmaya dayanır?', 'Liflerdeki gazların donmada büzülüp su çekmesi ve ısınmada genleşip itmesi', ['Gündüz güneş gören dış kabuğun fotosentez yaparak oksijen kabarcıklarıyla suyu yalnız aşağı doğru pompalaması', 'Gece donlarında köklerin tamamen kuruyup gündüz kar suyunu yaprak tomurcuklarından içeri çekmesi', 'Akçaağaç gövdesinin merkezindeki boşluğun mevsimlik gelgit çekimiyle yer altı suyunu vakumlaması'], 'Akçaağaçlarda ksilem lifleri su yerine gaz içerir; gece donarken buz kristalleri gazı sıkıştırıp kökten su çeker, gündüz ısındığında genleşen gazlar sükrozlu öz suyunda yüksek pozitif basınç oluşturur.'),
  ('Arkeologların ve iklimbilimcilerin eski ahşap örneklerde MS 774-775 ve MS 993-994 yıllarına ait tekil yaş halkalarında ani karbon-14 (¹⁴C) artışı saptayarak küresel takvimleri tek yıl hassasiyetiyle eşitlemesini sağlayan olaya ne ad verilir?', 'Miyake radyasyon olayı', ['Maunder tarihsel güneş lekesi minimumu dönemi', 'Milankoviç yörünge eksen eğikliği kayması', 'El Niño pasifik güney salınımı daralması'], 'Fusa Miyake tarafından Japon sediri halkalarında keşfedilen bu ani ¹⁴C sıçramaları, dev güneş fırtınalarının atmosferde ürettiği radyokarbonun aynı yıl dünyadaki tüm ağaçların halkasına kaydedilmesiyle oluşmuştur.'),
  ('Yaz ortasında kurak ve sıcak geçen bir günde dev bir ağacın gövdesine hassas çap ölçer (dendrometre) bağlandığında öğleden sonra gövde çapının sabah saatlerine göre mikrometre düzeyinde daraldığı, gece ise tekrar genişlediği görülür. Bunun nedeni nedir?', 'Gündüz terleme gerilimiyle dokulardan su çekilip gece yeniden dolması', ['Ağacın gündüz solunumla odun liflerini yakıp gece karanlığında yeni yaş halkasını tek seferde örmesi', 'Sıcak havada gövde kabuğundaki süberin tabakasının büzüşüp gece çiyle on kat şişmesi', 'Güneş ışığının vasküler kambiyum hücrelerini gündüz öldürüp gece kök meristeminden yenilemesi'], 'Kohezyon-gerilim teorisi uyarınca gündüz yapraklardan kaybedilen su ksilem su sütununda negatif basınç (gerilim) yaratır ve elastik dokulardan su çekilerek gövde çok hafif büzülür; gece stomalar kapanınca çap toparlanır.'),
  ('Akçaağaç tohumu (helikopter böceği olarak da bilinen samara) daldan koptuğunda taş gibi dik düşmek yerine kendi ağırlık merkezi etrafında hızla dönerek yavaşça süzülür. Bu otorotasyon hareketinin aerodinamik sırrı nedir?', 'Kanat ön kenarında oluşan girdabın ek kaldırma kuvveti yaratması', ['Tohumun içindeki ısınmış hava kesesinin sıcak hava balonu gibi meyveyi yukarı doğru itmesi', 'Kanat yüzeyindeki mikroskobik tüylerin yerçekimi ivmesini yarı yarıya sıfırlaması', 'Meyve sapının koparken zemberek gibi boşalarak kanada motorlu pervane itişi vermesi'], 'Biyofizik araştırmaları akçaağaç samarasının dönerken böcek ve yarasa kanatlarındakine benzer bir ön kenar girdabı (leading-edge vortex) oluşturduğunu, böylece havada çok daha uzun kalarak yatay rüzgârla uzağa taşındığını göstermiştir.'),
  ('Güneydoğu Asya yağmur ormanlarında yaşayan dev \'Cavan salatalığı\' (Alsomitra macrocarpa) sarmaşığının 13 santimetre kanat açıklığına sahip ince kağıtsı kanatlı tohumları havacılık tarihinde kime ne için ilham vermiştir?', 'Kuyruksuz uçan kanat ve planör tasarımlarına', ['Ters yöne dönebilen çift pervaneli askeri helikopter motorlarına esin vermiştir', 'Denizaltıların su altında sessiz ilerleyen yunus kuyruğu dümenlerine örnek olmuştur', 'Uzay kapsüllerinin atmosfere girerken açılan kubbeli fren paraşütlerine model olmuştur'], 'Alsomitra macrocarpa tohumları durgun orman havasında mükemmel süzülme oranıyla geniş sarmallar çizerek uçar; 20. yüzyıl başında Igo Etrich ve Horten kardeşlerin kuyruksuz \'uçan kanat\' uçak tasarımlarına doğrudan ilham kaynağı olmuştur.'),
  ('Orkide (Orchidaceae) kapsüllerinden saçılan milyonlarca mikroskobik \'toz tohumun\' rüzgârla çok uzaklara uçabilmesini sağlayan yapısal özelliği ve bunun çimlenme aşamasında yarattığı zorunluluk nedir?', 'Endospermsiz hafif tohumlardır; çimlenirken mikoriza mantarına muhtaçtırlar', ['İçleri helyum ve azot gazıyla dolu sert kabuklu kürelerdir; çimlenmek için yalnız orman yangını külüne gereksinim duyarlar', 'Yoğun yağ damlacıkları içerdikleri için su yüzeyinde uçarlar; çimlenmek için kuşların sindirim kanalından geçmek zorundadırlar', 'Klorofilli tam gelişmiş yaprakçıklar taşıdıkları için havada fotosentez yaparlar; yalnız çıplak granit kayalarda kök salarlar'], 'Bir orkide kapsülünde un tozu inceliğinde yüz binlerce endospermsiz tohum bulunur; rüzgârla uzağa taşınırlar fakat kendi yedek besinleri olmadığından doğada uygun mikorizal mantar hifiyle buluşmadan fide geliştiremezler.'),
  ('Tropikal Amerika ormanlarında yetişen ve gövdesi konik dikenlerle kaplı \'dinamit ağacı / kum saati ağacı\' (Hura crepitans), olgunlaşan kabak biçimli odunsu meyveleriyle nasıl bir tohum yayma rekoruna sahiptir?', 'Kuruyan meyve dilimleri patlayarak tohumları kırk-yetmiş metre uzağa fırlatır', ['Ağır meyveler nehir suyuna düşüp dibe batarak tatlı su kaplumbağaları tarafından yüz kilometre taşınır', 'Meyve içinden sızan tatlı nektar sayesinde gece yarasaları tohumları mağara tavanlarına yapıştırır', 'Tohumlar mikroskobik paraşüt tüyleriyle stratosfer rüzgârlarına kapılarak okyanus aşırı kıtalara uçar'], 'Sütleğengillerden Hura crepitans\'ın odunlaşmış karpelleri kururken muazzam mekanik kuruma gerilimi biriktirir ve patlayıcı dehisens ile tohumlarını saniyede 70 metreye varan hızla fırlatır.'),
  ('Turnagagası ve \'dönbaba / çobaniğnesi\' (Erodium cicutarium) bitkilerinin uzun gagalı tohumlarının hem rüzgârla dağıldıktan hem de yere düştükten sonra gece-gündüz nem değişimiyle kendi kendine toprağın içine vidalanarak gömülmesi nasıl işler?', 'Higroskopik gaganın kuruda kıvrılıp nemde açılarak tohumu toprağa itmesiyle', ['Tohum ucundaki asidik salgının kireçli kayaları eriterek beş santimetre derinlikte silindirik kuyu açmasıyla', 'Karıncaların sarmal gagayı anten sanarak tohumu zorla yer altı kuluçka odalarına çekmesiyle', 'Yağmur damlalarının tohumun arkasındaki geniş şapkaya çekiç gibi vurarak onu çamura çakmasıyla'], 'Erodium tohumlarının uzun kuyruğu (awn) nem aldığında doğrulur, kuruduğunda tirbuşon gibi döner; tohum üzerindeki geriye dönük sert kıllar geri çıkışı önlediği için her döngüde tohum toprağa biraz daha gömülür (ototripanokori).'),
  ('Acı biber (Capsicum) meyvelerine yakıcı acılığı veren \'kapsaisin\' maddesinin memeli hayvanların ağzındaki TRPV1 ağrı reseptörlerini şiddetle yakarken ardıç kuşu ve bülbül gibi kuşları hiç etkilememesinin bitkiye sağladığı yarar nedir?', 'Tohumu ezen kemirgenleri caydırırken bütün yutan kuşlarla yayılmayı sağlamak', ['Kuşların vücut sıcaklığını elli dereceye çıkararak tohumların kuşun midesindeyken çiçek açmasını sağlamak', 'Memeli hayvanların biber tarlasından kaçarken ayaklarıyla toprağı kazıp biber köklerini havalandırmasını sağlamak', 'Kapsaisin maddesinin kuş tüylerini kırmızıya boyayarak yırtıcı şahinleri biber çalılarından uzaklaştırmak'], 'Yönlendirilmiş caydırıcılık (directed deterrence) hipotezinin en klasik örneğidir: Fareler biber tohumlarını çiğneyip öldürür (tohum avcısı), kuşların ise dişleri yoktur ve kapsaisin reseptörleri duyarsız olduğundan ideal tohum yayıcılardır.'),
  ('Amazon yağmur ormanlarının dev ağacı \'Brezilya cevizi\'nin (Bertholletia excelsa) gülle kadar ağır ve taş gibi sert odunsu kapsül meyveleri yere düştükten sonra içindeki tohumlar doğada yalnızca hangi hayvan sayesinde serbest kalıp yayılabilir?', 'Kapsülü kemirip açan ve fazla tohumları gömen aguti kemirgeni sayesinde', ['Meyveleri gagasıyla havada yakalayıp kıran tukan kuşları ve makav papağanları sayesinde', 'Nehir taşkınlarında kapsülleri yutup çamurlu kıyılara bırakan dev tatlı su balıkları sayesinde', 'Kapsül duvarını formik asitle eriterek tohumları yaprak yuvalarına taşıyan yaprakkesen karıncalar sayesinde'], 'Brezilya cevizi hem tozlaşmada uzun dilli orkide arılarına hem de tohum yayılımında odunsu kapsülü açabilen tek orman hayvanı olan agutilere (Dasyprocta) bağımlıdır; bu yüzden plantasyon yerine doğal ormanda meyve verir.'),
  ('Amazon Havzası\'ndaki mevsimlik su basar \'várzea\' ormanlarında ağaçların tam nehir sularının ormanı bastığı aylarda olgun meyvelerini suya dökmesi ve \'tambaqui\' (Colossoma macropomum) gibi iri balıkların bu meyveleri yiyip tohumları akıntı yukarısına taşıması nasıl adlandırılır?', 'İhtiyokori (balıklarla tohum yayılması)', ['Anemokori (alize rüzgârlarıyla tohum yayılması)', 'Mirmokokori (su karıncalarıyla tohum yayılması)', 'Herpetokori (ağaç kurbağalarıyla tohum yayılması)'], 'Güney Amerika su basar ormanlarında kauçuk ağacı akrabaları ve palmiyeler dahil yüzlerce ağaç türü meyvelerini taşkın döneminde düşürür; meyve yiyen balıklar tohumları kilometrelerce akıntı tersine taşıyabilen kilit yayıcılardır.'),
  ('Hint Okyanusu\'ndaki Mauritius Adası\'na özgü \'Tambalacoque\' (Sideroxylon grandiflorum) gibi bazı kalın çekirdekli ada ağaçlarının genç bireylerinin azalması, 17. yüzyılda soyu tükenen \'dodo kuşu\' ve dev kaplumbağalarla nasıl ilişkilendirilmiştir?', 'İri meyve yiyici hayvanların taşlık ve sindirim kanalı taş gibi sert çekirdeği aşındırıp uzağa taşıdığı için onların yok oluşuyla yayılmanın aksaması', ['Dodo kuşlarının bu ağaçların köklerinde yuva kazarak toprağa her yıl tonlarca azotlu deniz yosunu gömmesi', 'Dev kaplumbağaların ağacın kabuğunu kemirerek çiçek açmasını sağlayan yaralanma hormonlarını salgılatması', 'Bu hayvanların soyu tükenince adadaki rüzgâr yönünün değişerek polenleri tamamen okyanusa savurması'], 'Stanley Temple\'ın ünlü \'dodo ağacı\' çalışması (sonradan dev Mauritius kaplumbağalarının da başrolde olduğu anlaşılmıştır), nesli tükenen ada megafaunasının bitki tohum yayılımında bıraktığı \'ekolojik anakronizm\' boşluğunu ortaya koymuştur.'),
  ('Anadolu ormanlarındaki \'yabani siklamen\' (Cyclamen) bitkisinde çiçek açtıktan sonra çiçek sapının sarmal yay (tirbuşon) gibi kıvrılarak olgunlaşan kapsülü toprak yüzeyine indirmesinin ekolojik amacı nedir?', 'Elaiosom taşıyan şekerli-yağlı tohumları tam toprak yüzeyinde gezen karıncaların kolayca bulup taşıyabileceği hizaya teslim etmek', ['Tohumları rüzgârdan tamamen gizleyerek bin yıl boyunca hiç çimlenmeden ana soğanın içinde saklamak', 'Kapsülü yer altı sularına batırarak tohumların yalnızca balıklar aracılığıyla göllere yayılmasını sağlamak', 'Çiçek sapındaki klorofili toprağa gömerek bitkinin kış aylarında kök çürüklüğünden korunmasını sağlamak'], 'Siklamenlerde döllenme sonrası pedisel (çiçek sapı) tirbuşon gibi büzülerek meyveyi yere çeker; kapsül açıldığında yapışkan-yağlı tohumlar karıncalar (mirmokokori) tarafından çevredeki kuytu noktalara taşınır.'),
  ('Tropikal yağmur ormanlarında yetişen bir incir veya maun ağacının dibine düşen binlerce tohumun neredeyse tamamı böcek ve mantarlarca yok edilirken, kuşların 100 metre uzağa taşıdığı tek tük tohumların fidan olma şansının çok yüksek olması ekolojide hangi hipotezle açıklanır?', 'Janzen-Connell hipotezi (türe özgü tohum avcıları ve patojenlerin ana ağaç altında yoğunlaşması)', ['Gause rekabetçi dışlama ilkesi (iki farklı türün aynı anda aynı güneş ışığını kullanamaması)', 'Liebig minimum yasası (büyümenin en kıt bulunan tek bir mineral tarafından sınırlandırılması)', 'Ada biyocoğrafyası kuramı (anakaraya uzaklığın göç hızını düşürüp yok oluşu artırması)'], 'Daniel Janzen ve Joseph Connell\'in açıkladığı bu mekanizma, ana ağacın çevresinde ona özgü mantar ve tohum böceklerinin biriktiğini; uzağa yayılan tohumların bu \'ölüm bölgesinden\' kurtulduğunu ve böylece tropik ormanda tek bir türün tekel kuramadığını gösterir.'),
  ('Orta Asya ve Sahra gibi su tablasının çok derinde olduğu çöllerde yaşayan \'deve dikeni\' (Alhagi maurorum) ve \'mesquite\' (Prosopis) çalılarının yer üstü boyu 1-2 metre iken köklerinin 15 ila 50 metre derine inmesi hangi kuraklık stratejisidir?', 'Freatofit (derin yer altı taban suyuna ulaşarak kuraklıktan etkilenmeme) stratejisi', ['Efemer (yağmurdan hemen sonra iki haftada tohum verip kuruma) stratejisi', 'Poikilohidrik (tamamen kuruyup taşlaştıktan sonra yağmurla dirilme) stratejisi', 'Epifitik (ağaç dalları üzerinde çiy damlalarıyla tutunma) stratejisi'], 'Freatofit bitkiler çöl yüzeyindeki kavurucu kuraklığa katlanmak yerine enerjilerinin büyük kısmını yer altı su tablasına (freatik zon) ulaşan olağanüstü uzun kazık köklere yatırır.'),
  ('Güney Afrika\'nın taşlı çöllerinde yaşayan \'yaşayan taşlar\' (Lithops) bitkisinin neredeyse tüm gövdesini toprağın altına gömüp yüzeyde yalnızca çakıl taşı desenli iki yaprak ucunu (\'pencere yaprak\') bırakmasının işlevi nedir?', 'Otçullardan gizlenip serin toprak altında su kaybını önlerken üstteki saydam kristal pencerelerden yer altındaki klorofillere ışık indirmek', ['Üstteki taş benzeri yüzeyle yağmur suyunu süzerek doğrudan elli metre derindeki taban suyuna iletmek', 'Çakıl desenleriyle böcekleri yanıltıp yaprak arasına sıkıştırarak sindirim enzimleriyle eritmek', 'Güneş ışığını tamamen geri yansıtarak bitkinin fotosentez yerine topraktaki humustan beslenmesini sağlamak'], 'Lithops ve Fenestraria gibi \'pencere bitkilerinde\' fotosentetik mezofil dokusu kızgın çöl yüzeyinin altında serin kalır; yaprak tepesindeki klorofilsiz saydam kalsiyum oksalatlı pencere dokusu ışığı fiber optik gibi içeri dağıtır.'),
  ('Kurak ortamlarda tamamen kuruyup kırılgan bir ot yumağına dönüştüğü halde hücre zarlarını trehaloz ve sükroz şekerleriyle camlaştırarak koruyan, yıllar sonra bir damla su aldığında saatler içinde tekrar yemyeşil canlanan \'diriliş bitkisi\' (Selaginella lepidophylla / Eriha gülü) hangi fizyolojik gruba girer?', 'Kurumaya toleranslı (poikilohidrik) diriliş bitkileri', ['Tuz salgı bezli zorunlu halofit kıyı bitkileri', 'Su altı şerit yapraklı batık hidrofit bitkiler', 'Kışın ibre döken açık tohumlu orman ağaçları'], 'Çoğu damarlı bitki suyunun %30-50\'sini kaybedince ölürken, poikilohidrik \'diriliş bitkileri\' (örneğin Selaginella lepidophylla, Haberlea rhodopensis) suyunun %95\'ini kaybedip anhidrobiyoz durumuna geçebilir ve ıslanınca fotosenteze döner.'),
  ('Bozkır ve kumullarda yetişen birçok kurakçıl buğdaygilin (örneğin sorguç otu / Stipa ve kumul otu / Ammophila) öğle sıcağında düz yaprak ayalarını kendi içine doğru boru gibi kıvırmasını sağlayan özel hücreler hangileridir?', 'Üst epidermiste yer alan ve su kaybedince büzülen iri \'bülliform (motor) hücreler\'', ['Yaprak damarlarını dıştan kuşatan kalın duvarlı ölü sklerankima kılıf hücreleri', 'Kök ucunda yerçekimini algılayan nişasta tanecikli statolit hücreleri', 'Alt epidermiste uçucu yağ salgılayan çok hücreli başçıklı salgı tüyleri'], 'Stomaların bulunduğu yüzeyi rüzgârdan gizlemek için bülliform hücreler kuraklıkta turgorunu hızla kaybedip büzülür; yaprak silindir gibi dürülerek içerde nemli bir mikro oda oluşturur ve su alınca tekrar açılır.'),
  ('Mangrov ağaçlarında (örneğin Rhizophora) tohumun ana ağaçtan kopup tuzlu çamura düşmeden önce henüz dal üzerindeyken çimlenip 20-40 santimetrelik yeşil mızrak biçimli bir fidecige (propagül) dönüşmesi olayına ne ad verilir?', 'Vivipari (canlı doğuran / ana bitki üzerinde çimlenme)', ['Apomiksis (döllenmesiz tohum oluşturma)', 'Partenokarpi (tohumsuz meyve bağlama)', 'Vernalizasyon (soğuklama ile çiçeklenme)'], 'Tuzlu ve gelgitli balçıkta küçük bir tohumun çimlenmesi neredeyse imkânsızdır; vivipar mangrov fideleri ağaçta gelişir, düştüğünde ya mızrak gibi dik çamura saplanır ya da gelgitle yüzüp sığlıkta hemen kök salar.'),
  ('Tropikal ağaç dallarında toprağa hiç değmeden yaşayan epifit orkidelerin (örneğin Phalaenopsis, Vanda) havada sarkan gümüşi-beyaz köklerini dıştan saran süngerimsi ölü hücre katmanına (\'velamen\') neden ihtiyaç duyulur?', 'Yağmur başladığı anda suyu ve içinde çözünmüş besinleri saniyeler içinde sünger gibi emip yağmur dinince kökün kurumasını önlemek için', ['Konak ağacın kabuğunu delerek ksilem ve floem borularından parazitik öz suyu çekmek için', 'Köklerin ağırlığını on kat artırarak orkidenin fırtınada daldan kopup toprağa düşmesini sağlamak için', 'Geceleri biyolüminesans ışık yayarak tozlayıcı güveleri kök uçlarına yönlendirmek için'], 'Çok katlı ölü epidermis olan \'velamen radicum\' kuruyken içi hava dolu olduğu için gümüşi beyaz görünür; ıslanır ıslanmaz şeffaflaşarak suyu hapseder ve altındaki klorofilli yeşil kök korteksinin fotosentez yapmasına da izin verir.'),
  ('Amerika\'nın sıcak ve nemli bölgelerinde telefon tellerinden ve meşe dallarından gri sakallar gibi sarkan \'İspanyol yosunu\' (Tillandsia usneoides) adlı çiçekli bitki, hiç kökü olmadığı halde su ve mineralleri nasıl karşılar?', 'Tüm gövde ve yapraklarını kaplayan kalkan biçimli emici pullarla (trikomlarla) havadaki sisi, çiyi ve toz minerallerini doğrudan tutarak', ['Telefon tellerindeki bakır iyonlarını ve ağaç kabuğundaki floem şekerlerini emeçleriyle çekerek', 'Yalnızca kara yosunlarıyla simbiyotik ortaklık kurup spor keselerinden besin üreterek', 'Yağmurlu gecelerde geçici hava kökleri uzatıp yerdeki topraktan su çektikten sonra köklerini geri toplayarak'], 'Adında \'yosun\' geçse de Tillandsia usneoides ananasgiller (Bromeliaceae) familyasından gerçek çiçekli bir \'hava bitkisidir\' (aerofit/epifit); ergin bireyde kök yoktur, su emilimini tüm yüzeydeki gümüşi pullar yapar.'),
  ('Güneydoğu Asya yağmur ormanlarında yaşayan dev \'ibrik otları\' (Nepenthes rajah ve N. lowii) türlerinin bir kısmının böcek yakalamayı azaltıp ağaç sivrifarelerinin ve yarasaların dışkısını toplayacak klozet/barınak şekline evrimleşmesi ne gösterir?', 'Yüksek dağ bulut ormanlarında böcek kıtlaşınca bitkinin azot kaynağını memeli dışkısına kaydıran mutualist bir uyum geliştirdiğini', ['İbrik otlarının bu memelileri zamanla içine düşürüp tamamen sindirmek için tuzak boyunu büyüttüğünü', 'Bitkinin memeli dışkısındaki tohumları çimlendirerek kendi içinde parazit ağaç yetiştirdiğini', 'Klorofilini yitiren ibrik otunun yalnız yarasa solunumundan çıkan karbondioksitle yaşadığını'], 'Borneo dağlarındaki Nepenthes lowii kapağında lezzetli nektar sunarak ağaç sivrifaresini tam ibrik ağzına oturtur ve azotça zengin dışkısını toplar; N. hemsleyana ise yarasalara yankı yapan tünek sağlayıp guano ile beslenir.'),
  ('Durgun tatlı sularda köksüz yüzen \'su kesesi / su miskotu\' (Utricularia) bitkisi, bitkiler âleminin en hızlı av yakalama hareketini (yaklaşık 1 milisaniyede) nasıl gerçekleştirir?', 'Suyunu dışarı pompalayarak içerde vakum yarattığı küçük keseciklerin kapak tüyüne su piresi değdiğinde kapağı açıp avı suyla birlikte içeri vakumlayarak', ['Su altındaki uzun kamçılı yapraklarını zıpkın gibi fırlatıp küçük balıkları delerek', 'Suya elektrik akımı vererek çevresindeki tüm kabukluları bayıltıp yaprak arasına toplayarak', 'Su yüzeyinde şişen gaz keselerini patlatıp şok dalgasıyla böcekleri dibe batırarak'], 'Türkiye sulak alanlarında da bulunan Utricularia (Lentibulariaceae), milimetrik \'emme tuzaklarının\' (utrikül) içindeki suyu dışarı atarak duvarları içe çökertir; tetik kılına dokunulduğu anda kapak içeri açılır ve av 600 g ivmeyle yutulur.'),
  ('Koyu gölgeli kayın ve çam ormanlarının zemininde tek bir yeşil klorofil zerresi taşımadan bembeyaz veya sarımsı-pembe çiçek sapları halinde yükselen \'kuşyuvası orkidesi\' (Neottia nidus-avis) ve \'çam kenevirciği\' (Monotropa hypopitys) besinlerini nereden alır?', 'Çevredeki ağaçlarla ortak yaşayan mikoriza mantarlarının hiflerine bağlanarak ağaçların ürettiği karbonu mantar üzerinden çekerler', ['Doğrudan kendi salgıladıkları selülaz enzimleriyle yerdeki kütükleri eriterek çürükçül bakteriler gibi beslenirler', 'Toprak altındaki solucanları ve böcek larvalarını köklerindeki yapışkan tuzaklarla yakalayıp sindirirler', 'Yalnızca geceleri ay ışığının morötesi dalga boylarını kullanarak renksiz plastitleriyle şeker üretirler'], 'Eskiden \'çürükçül (saprofit) çiçekli bitki\' sanılan bu klorofilsiz türlerin ölü maddeyi doğrudan parçalayamadığı, bunun yerine ormandaki mikorizal ağa sızarak mantar aracılığıyla komşu ağaçlardan karbon çaldığı (mikoheterotrofi) kanıtlanmıştır.'),
  ('Muğla Köyceğiz\'den Toroslar\'a ve Eskişehir-Sivas kuşağına kadar uzanan \'serpantin (ultramafik)\' anakayalar üzerinde çam ve meşe boyları bodurlaşırken buraya uyum sağlamış \'Alyssum murale\' (kuduz otu) gibi bitkilerin yapraklarında kuru ağırlığın %1-2\'si oranında nikel biriktirmesi nasıl adlandırılır?', 'Ağır metal hiperakümülasyonu (aşırı biriktiricilik) ve fitomadencilik potansiyeli', ['Tuz salgı bezleriyle sodyum dışlama (halofitik rekresyon) mekanizması', 'Kök yumrularında atmosferik azot fiksasyonu', 'Yaprak kenarlarından gutasyonla kalsiyum karbonat damlatma süreci'], 'Serpantin topraklar kalsiyumca fakir, magnezyum, nikel, krom ve kobaltça zehirli düzeyde zengindir; Türkiye florasındaki birçok endemik Brassicaceae türü (Alyssum/Odontarrhena, Thlaspi/Noccaea) nikeli kofulda depolayarak hem böceklerden korunur hem de toprak temizliğinde (fitoremediasyon) kullanılır.'),
  ('Brezilya savanları olan \'Cerrado\' biyomunda ve Akdeniz-Afrika geçişlerinde görülen bazı çalıların yer üstünde yalnızca 30-50 santimetre kısa sürgünler çıkarırken toprak altında dev bir ağaç kütüğü büyüklüğünde odunsu gövde (\'ksilopodyum\') saklamasına ne ad verilir?', 'Yer altı ormanı', ['Hava köklü epifitik kanopi asması formu', 'Yüzeysel saçak köklü bataklık sazlığı formu', 'Tek yıllık kuraklıktan kaçan efemer ot formu'], 'Sık tekrarlanan savan yangınları ve uzun kurak mevsim karşısında \'yer altı ağaçları\' biyokütlelerinin %70-90\'ını toprak altındaki su-nişasta depolu odunsu ksilopodyumda tutar; yangın geçtikten birkaç gün sonra yerden çiçek ve yaprak fışkırtır.'),
  ('Akdeniz orman altlarında kış ortasında koyu yeşil \'yapraklarının\' tam ortasında kırmızı mercan gibi tek bir üzümsü meyve taşımasıyla şaşırtıcı bir görüntü sunan \'tavşanmemesi / ölmez diken\' (Ruscus aculeatus) bitkisinde meyvenin yaprak ortasında durmasının gerçek nedeni nedir?', 'Yaprak sanılan o yassı ve ucu dikenli yapıların gerçekte \'filloklad\' adı verilen yassılaşmış yan dallar olması', ['Kuşların başka çalılardan topladıkları kırmızı meyveleri reçineyle bu bitkinin yaprak üstüne yapıştırması', 'Böcek sokması sonucunda yaprak ortasında meyveye çok benzeyen kırmızı küresel bir mazı gelişmesi', 'Bitkinin çiçek tomurcuklarını kökten yaprak damarı içine taşıyıp epidermisi delerek açtırması'], 'Gerçek bir yaprağın ayası üzerinde normalde çiçek ve meyve tomurcuğu oluşmaz; Ruscus\'ta gerçek yapraklar mikroskobik zarsı pullara indirgenmiştir, \'yaprak\' görünen sert yeşil organlar ise ortasındaki boğumdan çiçek açan yassı sürgünlerdir (filloklad).'),
  ('Avustralya kökenli \'akasyaların\' (örneğin Kıbrıs akasyası - Acacia saligna) yeni çimlenen fidesinde tüysü bileşik yapraklar görülürken ağaç büyüdüğünde ayaların kaybolup yalnızca orak biçimli düz yeşil yaprakların kalması nasıl gerçekleşir?', 'Bileşik yaprak ayası körelirken \'yaprak sapının\' (petiyol) yassılaşıp genişleyerek \'fillod\' adı verilen kurakçıl yaprak görevini üstlenmesiyle', ['Ağacın kök boğazından başka bir söğüt türünün aşılanmaksızın kendiliğinden sürgün çıkarmasıyla', 'Çiçek taç yapraklarının döllenmeden sonra yeşil renge dönüp kış boyu dalda fotosentez yapmasıyla', 'İnce sürgün kabuklarının soyularak dal uçlarında şerit biçimli kurdeleler halinde asılı kalmasıyla'], 'Fillod (yassılaşmış yaprak sapı), gerçek ince yaprak ayasına göre daha kalın kütikulalı, dikey duruşlu ve kuraklığa çok daha dirençlidir; fidedeki ilk tüysü yapraklar ise türün evrimsel geçmişini (ontogeni) ele verir.'),
  ('Soğan, safran, çiğdem ve lale gibi geofit bitkilerin tohumdan çimlenen genç soğanlarının yıllar içinde toprak yüzeyinden uygun derinliğe (örneğin 10-15 cm alta) kendi kendine inmesini sağlayan özel kök tipi hangisidir?', 'Büzülerek soğanı aşağı çeken \'çekici (kontraktil) kökler\'', ['Toprak üstüne çıkarak hava alan \'pnömatofor kökler\'', 'Ağaç kabuğuna yapışan \'epifitik velamen kökler\'', 'Yatay uzanarak yeni gövdeler çıkaran \'klonal sürgün kökleri\''], 'Yüzeye düşen tohumdan oluşan yavru soğan kış donuna ve yaz sıcağına açıktır; kontraktil köklerin korteks hücreleri enine genişleyip boyuna kısaldığında kök akordeon gibi büzülür ve soğanı güvenli toprak derinliğine çeker.'),
  ('Böcekçil \'ibrik otu\' (Nepenthes) ve Kuzey Amerika \'boru çiçeği\' (Sarracenia) bitkilerinde tuzağın kenar halkasının (\'peristom\') yağmurlu ve nemli havalarda karıncaların hiç tutunamayıp anında içine kaydığı sürtünmesiz bir tuzağa dönüşmesinin fiziksel nedeni nedir?', 'Mikroskobik oluklu yüzeyin suyu hızla yayarak böceğin ayak yastıkçıkları ile yüzey arasına kaygan bir su filmi sokması', ['Yağmur değdiğinde peristom yüzeyinden silikon ve parafin mumu fışkırarak yüzeyi yağlaması', 'Böceğin ağırlığıyla tuzağın ağız kenarının içeriye doğru menteşeli kapak gibi çökmesi', 'Nemli havada sindirim sıvısının taşarak tuzağın dış yüzeyini yapışkan tutkalla sıvaması'], 'Kuru havada karıncalar peristom üzerinde rahatça yürüyüp nektar yiyerek diğer karıncalara haber verir; sabah çiyi veya yağmurla hidrofilik mikro oluklar su filmiyle kaplandığında böcek ayakları kızaklar (aquaplaning) ve karınca kolonisi topluca avlanır.'),
  ('Avustralya ve Güney Afrika\'nın yangına eğilimli ekosistemlerinde (fynbos, mallee, kwongan) yüzlerce bitki türünün tohumlarının ısıyla çatlamak yerine doğrudan \'yangın dumanı\' veya yanmış odun suyuna maruz kalınca çimlenmesini uyaran kimyasal sinyal grubu hangisidir?', 'Yanan bitki selülozundan türeyen \'karrikin\' bileşikleri', ['Yeşil yapraklardan salgılanan uçucu \'jasmonik asit\' esterleri', 'Çürüyen meyvelerden yayılan \'etilen\' gazı molekülleri', 'Kök nodüllerinde sentezlenen \'leghemoglobin\' proteinleri'], 'Adını Avustralya Nyungar Aborjin dilinde duman anlamına gelen \'karrik\' kelimesinden alan karrikinler (butenolid türevleri), yangın sonrası yağmurla toprağa sızarak ışık ve rakiplerin temizlendiğini bekleyen tohumlara bildirir.'),
  ('Dünyanın en küçük çiçekli bitkisi unvanını taşıyan ve durgun tatlı su yüzeylerini yeşil mercimek taneleri gibi kaplayan \'su mercimeği / Wolffia\' (Araceae) yüksek üreme hızına ulaşırken hangi organlarından tamamen vazgeçmiştir?', 'Kök, gövde ve yaprak ayrımı tamamen kalkmış; bir milimetrelik yeşil talus-benzeri gövdecikten tomurcuklanarak çoğalır hale gelmiştir', ['Kloroplastlarını ve tüm fotosentez enzimlerini bırakıp yalnızca kurbağa larvalarının dışkısıyla beslenir olmuştur', 'Çiçek ve tohum oluşturma yeteneğini tümüyle yitirip yalnız rüzgârla uçan eğrelti sporları üretir olmuştur', 'Hücre çeperlerini tamamen eriterek su içinde amip gibi yalancı ayaklarla hareket eden tek hücreye dönüşmüştür'], 'Su mercimeği alt ailesinden Wolffia arrhiza ve W. globosa (0,5-1 mm) köksüz ve damarsızdır; uygun besinli suda her 30-36 saatte bir biyokütlesini ikiye katlayabilen fakat mikroskobik bir çiçeği de koruyan en indirgenmiş kapalı tohumludur.'),
  ('Yabani kiraz / kuş kirazı (Prunus avium) ağacının yaprak ayasının hemen tabanında, yaprak sapı üzerinde yer alan iki adet kırmızımsı küçük siğil (\'ekstrafloral nektar bezi\') ağaca nasıl bir ekolojik yarar sağlar?', 'Şekerli sıvıyla karıncaları çekip yaprak yiyen tırtıllara karşı koruma kurar', ['Fazla yağmur suyunu yaprak damarlarından dışarı atarak kök çürümesini engeller', 'İlkbahar polenlerini yapışkan damlada toplayıp çiçeklenmeden tozlaşmayı sağlar', 'Kış donlarında gliserin salgılayarak tomurcukların sıfırın altında donmasını önler'], 'Çiçek dışı (ekstrafloral) nektar bezleri tozlaşma yapmaz; şeker ve amino asit damlacıklarıyla karıncaları ve parazitoit yaban arılarını yaprak üzerinde devriye gezmeye teşvik ederek otçul böcek baskısını düşürür.'),
  ('Akdeniz maki kuşağında ilkbaharda portakal çiçeği gibi hoş kokulu beyaz çiçekler açan, küremsi sert tohumlarından tespih dizilen ve meyve kabuğundaki \'saponin\' geçmişte derelerde balıkları sersemletmekte kullanılmış çalı hangisidir?', 'Tespih çalısı / Ayıfındığı (Styrax officinalis)', ['Yabani menengiç ağacı (Pistacia terebinthus)', 'Herdemyeşil akçakesme çalısı (Phillyrea latifolia)', 'Sarı çiçekli katırtırnağı (Spartium junceum)'], 'Styracaceae familyasından Styrax officinalis meyve kabuklarında suyla çalkalanınca köpüren ve balık solungaçlarını geçici etkileyen triterpenik saponinler taşır; bu yöntem doğaya zararlı olduğu için yasaklanmıştır.'),
  ('Karadeniz ve Marmara orman altlarında yetişen \'çobanpüskülü\' (Ilex aquifolium) ağacında alt dallardaki yaprakların kenarları çok sert batıcı dikenli iken 4-5 metre yukarıdaki üst dal yapraklarının dikensiz ve düz kenarlı olması neyle açıklanır?', 'Otçul memelilerin kemirdiği alt dallarda epigenetik mekanizmayla dikenli yaprak üretilmesiyle', ['Üst dalların güneşte tamamen kuruyup dikenlerini her sonbaharda rüzgârla dökmesiyle', 'Ağacın alt gövdesinin kermes meşesi, üst gövdesinin ise defne ağacıyla melezlenmesiyle', 'Yüksek dallarda rüzgâr basıncının yaprak kenarındaki dikenleri mekanik olarak köreltmesiyle'], 'Fenotipik plastisitenin çarpıcı bir örneği olan çobanpüskülünde karaca ve geyiklerin ulaştığı alt dallarda DNA metilasyonu değişerek batıcı dikenli yapraklar yapılır, hayvan boyunu aşan üst taçta ise enerji tasarrufu için düz yaprak üretilir.'),
  ('Anadolu tarla kenarlarında yetişen dikenli \'kadıntuzluğu / kızambık\' (Berberis vulgaris) çalısının geçmişte buğday tarlalarının çevresinden sökülüp uzaklaştırılmasının tarımsal gerekçesi nedir?', 'Buğday kara pası mantarının eşeyli üreme evresini geçirdiği zorunlu ara konak olması', ['Köklerinden salgıladığı zehirli alkaloitlerle yüz metre çevredeki buğday tohumlarını yakması', 'Sarı çiçeklerinin tüm tozlayıcı arıları çekerek buğday başaklarının tozlaşmasını engellemesi', 'Topraktaki tüm nitratı emip yapraklarında tuz kristali halinde biriktirerek tarlayı çoraklaştırması'], 'Buğdayda büyük ürün kaybı yaratan Puccinia graminis (kara pas) mantarı karmaşık yaşam döngüsünün eşeyli aşamasını Berberis yapraklarında tamamlar; buğday rüzgârla tozlaştığı için arı rekabeti zaten söz konusu değildir.'),
  ('Kadıntuzluğu (Berberis vulgaris) çiçeğinin dibindeki nektarı emmek isteyen bir arı hortumunu içeri uzattığında çiçekteki altı erkek organın (stamen) saniyenin onda biri sürede yay gibi içeri fırlayıp arının başına polen çarpması hangi harekete örnektir?', 'Dokunma uyarısıyla tetiklenen hızlı turgor hareketine (tigmonasti)', ['Güneş ışığının yönüne doğru gerçekleşen yavaş oksin büyümesine (fototropizma)', 'Yerçekimi ivmesiyle polen keselerinin aşağı sarkmasına (pozitif geotropizma)', 'Gece-gündüz sıcaklık farkıyla taç yaprakların açılıp kapanmasına (termonasti)'], 'Berberis erkek organ iplikçiklerinin tabanı dokunmaya duyarlıdır; böcek değdiği anda hücre zarları depolarize olup su çıkar ve başçık mancınık gibi böceğe çarparak polen israfını önler.'),
  ('Akdeniz ve Ege\'nin taşlık kireçli yamaçlarında yaygın olan \'çiçek dişbudağı\' (Fraxinus ornus) ağacı, diğer dişbudak türlerinden ilkbahardaki görünümü ve gövde öz suyu bakımından nasıl ayrılır?', 'Gösterişli beyaz kokulu taç yapraklarla böceklerle tozlaşır ve gövdesinden manitolce zengin \'kudret helvası\' sızar', ['Kış ortasında yapraksızken yalnız rüzgârla tozlaşır ve gövdesinden kauçuk lateksi toplanır', 'Dört mevsim iğne yapraklarını korur ve kozalaklarından acı katran yağı damıtılır', 'Yalnızca su basar longoz bataklıklarında yetişir ve köklerinden kırmızı boya çıkarılır'], 'Adi dişbudak ve sivri meyveli dişbudak taç yapraksız olup rüzgârla tozlaşırken, çiçek dişbudağı (Fraxinus ornus) sonradan yeniden böcekle tozlaşmaya dönmüş kremsi beyaz taç yapraklı salkımlar açar ve çizilen gövdesinden tatlı manna (manitol) elde edilir.'),
  ('Karadeniz ve Toroslar\'ın nemli yamaçlarında yetişen \'kayacık\' (Ostrya carpinifolia) ağacı gövde ve yapraklarıyla gürgene çok benzemesine karşın meyve salkımının hangi özelliğiyle gürgenden ilk bakışta ayrılır?', 'Tohumlarının şerbetçiotunu andıran şişkin kapalı zarsı kesecikler içinde toplanmasıyla', ['Üç parçalı düz açık kanatlı braktelerin ucunda fındık büyüklüğünde açık tohum taşımasıyla', 'Dikenli sert dört kapaklı odunsu bir kadeh içinde üç köşeli yağlı tohumlar barındırmasıyla', 'Parlak kırmızı renkli sulu etli üzümsü meyveler oluşturarak kuşlarla yayılmasıyla'], 'Gürgende (Carpinus) meyve üç loblu açık bir uçma yaprağına tutunurken, kayacıkta (Ostrya - hop-hornbeam) her fındıksı meyve içi hava dolu kapalı bir torbacık içindedir ve hem rüzgârda hem dere suyunda yüzebilir.'),
  ('Parfümeri ve tütsü yapımında binlerce yıldır çok yüksek fiyatlarla alıcı bulan gerçek \'Hint sandal ağacı\' (Santalum album), kerestesi dışındaki kök beslenme biçimiyle diğer orman ağaçlarından nasıl ayrılır?', 'Kendi yapraklarıyla fotosentez yaparken kök emeçleriyle komşu ağaçların köklerinden su ve mineral çeken yarı parazit ağaçtır', ['Toprağa hiç değmeden yalnızca dev bambuların üst dallarında yaşayan köksüz epifit bir çalıdır', 'Hiç klorofil taşımadığı için orman tabanındaki çürümüş hayvan kemiklerini eriterek beslenen saprofittir', 'Kök yumrularında kükürt bakterileri barındırarak kemosentezle karanlıkta şeker üreten tek ağaçtır'], 'Santalaceae (Ökseotugiller ile akraba) üyesi Santalum album zorunlu kök hemiparazitidir; fidanlıklarda ve plantasyonlarda yanına \'konak ağaç\' (örneğin baklagil ağaçları) dikilmezse sağlıklı büyüyüp kokulu öz odun üretemez.'),
  ('Doğu ve Güneydoğu Asya ormanlarındaki \'Aquilaria\' cinsi ağaçların sağlıklı odunu açık renkli ve kokusuz iken, paha biçilmez \'öd ağacı\' (agarwood / ud) kokulu koyu reçineli oduna dönüşmesi nasıl gerçekleşir?', 'Yaralanan gövdeye Phialophora gibi mantarlar girdiğinde ağacın savunma olarak yoğun aromatik reçine biriktirmesiyle', ['Ağacın köklerinin yalnızca yüz yılda bir tuzlu deniz suyuyla yıkanarak öz odunu siyahlaştırmasıyla', 'Erkek çiçek polenlerinin gövde kabuğundan içeri sızıp kış boyu fermente olmasıyla', 'Karınca kolonilerinin gövde merkezini oyup içine bal ve balmumu depolamasıyla'], 'Öd ağacı (ud) sağlıklı ağacın normal bir dokusu değil, mantar enfeksiyonu ve yaralanmaya karşı ağacın trake ve liflerini koyu seskiterpen-kromon reçineleriyle tıkayarak oluşturduğu patolojik bir savunma odunudur.'),
  ('Tropikal \'Myristica fragrans\' ağacının şeftaliye benzeyen sarı etli meyvesi yarıldığında tek bir meyveden dünya ticaretinde bilinen iki ayrı baharat birden elde edilir; bu iki baharat ve anatomik karşılıkları nedir?', 'İç tohum \'muskat (küçük hindistancevizi)\', tohumu dantel gibi saran kırmızı örtü ise \'masis\' baharatıdır', ['İç çekirdek \'karabiber\', dış etli meyve kabuğu ise kurutulunca \'yenibahar\' baharatıdır', 'Tohum kabuğu \'kakule\', meyve sapının şişkin kısmı ise \'zencefil\' baharatıdır', 'Çiçek çanak yaprağı \'yıldız anason\', tohumun kanat uzantısı ise \'tarçın\' baharatıdır'], 'Kuşları çekmek için koyu kahverengi muskat tohumunun dışını parlak kırmızı dantelsi bir \'arillus\' (tohum örtüsü) sarar; bu örtü soyulup kurutulduğunda \'macis\' (muskat çiçeği), iç tohum ise \'muskat cevizi\' olarak kullanılır.'),
  ('Kahve ağacı (Coffea arabica), çay çalısı (Camellia sinensis) ve kakao (Theobroma cacao) bitkilerinin yaprak ve genç tohumlarında birbirinden bağımsız olarak \'kafein\' alkaloidi sentezleyecek biçimde evrimleşmesinin bitkiye sağladığı temel fayda nedir?', 'Yüksek dozda böcek larvalarını felç edip komşu tohumları baskılarken nektardaki düşük dozla arıların çiçek belleğini güçlendirmek', ['Yaprak hücrelerinin donma noktasını eksi yirmi dereceye düşürerek kutup soğuklarına dayanıklılık kazandırmak', 'Klorofil molekülünün yerine geçerek kırmızı ışık olmadan gece karanlığında şeker sentezini sürdürmek', 'Topraktaki ağır metalleri bağlayıp gövde kabuğundan gaz halinde atmosfere uçurmak'], 'Kafein yakınsak evrimle gelişmiş çok işlevli bir savunma kimyasalıdır: Yaprak ve tohumda sümüklüböcek/böcek otçulluğunu ve rakip bitkileri (allelopati) önlerken, narenciye ve kahve nektarındaki eser kafein tozlayıcı arıların o çiçek kokusunu uzun süre hatırlamasını sağlar.'),
  ('Orta Amerika ormanlarında evrimleşen \'avokado\' (Persea americana) ağacının iri, yağlı ve tek dev çekirdekli meyvelerini bütünüyle yutup tohumunu kırmadan yayabilecek büyüklükte hiçbir doğal Amerikan kuşu veya maymunu bulunmaması nasıl açıklanır?', 'Soyu tükenen dev yer tembel hayvanları ve gomfoterlerle birlikte evrimleşmiş bir \'evrimsel anakronizm\' örneği olmasıyla', ['Avokado meyvelerinin gerçekte nehir akıntılarıyla okyanus aşırı yüzmek üzere içi hava dolu evrimleşmesiyle', 'Ağacın doğada hiç tohumla çoğalmayıp yalnızca rüzgârla kırılan dallarının köklenmesiyle yayılmasıyla', 'Tohumun yalnız volkanik patlamalar sırasındaki sarsıntıyla yamaç aşağı yuvarlanmak için ağırlaşmasıyla'], 'Pleistosen sonunda dev yer tembel hayvanları (Megatherium) ve mastodon benzeri gomfoterler yok olunca avokado, Osage portakalı ve Amerikan keçiboynuzu gibi dev meyveli ağaçlar ana yayıcılarını kaybetmiş; avokadoyu yok olmaktan erken dönem insan tarımı kurtarmıştır.'),
  ('Avokado (Persea americana) ağaçlarında erselik olan her tekil çiçeğin ilk gün dişi evrede açılıp kapanması, ertesi gün ise farklı bir saatte erkek evrede tekrar açılması (\'senkronize dikogami\') bahçe kurulumunda neyi zorunlu kılar?', 'Sabah dişi açan \'A tipi\' ile öğleden sonra dişi açan \'B tipi\' çeşitlerin bahçede birlikte dikilmesini', ['Ağaçların tozlaşabilmesi için her ilkbaharda tüm yapraklarının elle sıyrılıp budanmasını', 'Çiçeklerin yalnızca gece yarısı projektör ışığı tutularak yapay olarak uyandırılmasını', 'Dişi evreden erkek evreye geçişi durdurmak için toprağa yüksek dozda tuz verilmesini'], 'Kendi kendine tozlaşmayı (inbreeding) önleyen bu hassas saat mekanizmasında A grubu çeşitler sabah dişi / ertesi öğleden sonra erkek, B grubu çeşitler ise öğleden sonra dişi / ertesi sabah erkek açarak karşılıklı çapraz tozlaşır.'),
  ('Tropikal kumsallarda rüzgâr perdesi olarak dikilen \'demir ağacı / Avustralya çamı\' (Casuarina equisetifolia), çam ibresine çok benzeyen sarkık yeşil sürgünlerine rağmen neden çam değil kapalı tohumlu geniş yapraklı bir ağaçtır?', 'Gerçek çiçek ve meyve oluşturur; ibre sanılan yapılar eklemli yeşil sürgünler olup gerçek yapraklar boğumlardaki minik diş halkalarıdır', ['Gövdesinde reçine kanalları bulunur ancak tohumlarını yalnızca eğrelti otları gibi yaprak altı spor keselerinde üretir', 'Tek çenekli bir palmiye türü olup kış aylarında yeşil sürgünlerini tamamen toprağın altına çeker', 'Açık tohumlu mabet ağacının deniz tuzuyla mutasyona uğramış bodur bir kıyı varyetesidir'], 'Fagales takımından Casuarinaceae üyesi olan bu ağaç kuraklığa ve tuzlu rüzgâra karşı yapraklarını at kuyruğu (Equisetum) gibi minik pul dişlere indirgemiştir; ayrıca köklerinde kızılağaç gibi Frankia bakterileriyle azot bağlar.'),
  ('Kuzey Amerika\'daki Mojave Çölü\'nün simgesi olan ağaçsı monokotil \'Yucca brevifolia\' (Joshua ağacı) ile \'yuka güvesi\' (Tegeticula) arasındaki zorunlu karşılıklı bağımlılık (obligat mutualizm) nasıl işler?', 'Dişi güve polenleri topak yapıp tepeciğe aktifçe yerleştirdikten sonra yumurtalarını yumurtalığa bırakır ve larvalar tohumların yalnız küçük bir kısmını yer', ['Güve tırtılları ağacın tüm yapraklarını yiyerek su kaybını önler, karşılığında ağaç köklerinden güveye yer altı barınağı açar', 'Erkek güveler çiçek nektarını içerken kanatlarına bulaşan yapışkan meyveleri diğer çöl kaktüslerine taşır', 'Ağaç geceleri ısı üreterek güvenin donmasını engeller, güve ise gündüz çiçeğin ağzını ipekle kapatır'], 'Yuka çiçeği nektar üretmez; dişi Tegeticula güvesi özel ağız uzantılarıyla topladığı poleni bilinçli gibi stigmanın içine tıkıştırır ki larvalarını besleyecek tohumlar gelişsin; çok fazla yumurta bırakılan çiçekleri ise bitki seçici olarak döker!'),
  ('Geniş yapraklı ağaçlardan meşe, kestane ve dişbudak odunlarının enine kesitine büyüteçle bakıldığında yıllık halkanın ilkbahar kısmında çıplak gözle bile görülebilen çok iri gözenek dizileri varken kayın ve kavakta gözeneklerin homojen dağıldığı görülür. Bu iki odun tipi nasıl adlandırılır?', 'İlki \'halka traheli (ring-porous)\', ikincisi ise \'dağınık traheli (diffuse-porous)\' odundur', ['İlki \'trakeidsiz yumuşak odun\', ikincisi ise \'reçine kanallı açık tohumlu\' odundur', 'İlki \'kambiyumsuz monokotil gövde\', ikincisi ise \'sekonder kabuklu lian\' dokusudur', 'İlki \'yalancı halkalı kuraklık odunu\', ikincisi ise \'jelatinimsi çekme odunu\' yapısıdır'], 'Meşe, kestane, karaağaç ve dişbudak (halka traheliler) ilkbaharda yapraklanmadan hemen önce çok geniş çaplı su boruları (trakeler) üretir; kayın, gürgen, akçaağaç, kavak ve ıhlamur ise yıl boyu benzer çapta ince borular üretir.'),
  ('Meşe ve dişbudak gibi \'halka traheli\' ağaçların ilkbaharda çok geniş çaplı trake borularıyla muazzam hızda su taşıyabilmesine karşılık kış donlarında \'dağınık traheli\' kayın ve huşa göre ödediği fizyolojik bedel nedir?', 'Geniş borularda donma-çözülme sırasında çözünen gaz kabarcıklarının birleşerek iletimi kesen kış embolisi (kavitasyon) yaratması', ['Geniş trake borularının yaz ortasında fotosentez şekerleriyle tıkanarak kökleri aç bırakması', 'İlkbahar odununun çok ağır olması nedeniyle ağacın on metreden fazla boy atamaması', 'Geniş borulu ağaçların sonbaharda yapraklarını dökemeyip kış boyu terlemeye devam etmesi'], 'Geniş çaplı su borularında donarken buzdan dışlanan hava kabarcıkları büyük olduğu için ilkbaharda su çözüldüğünde tekrar erimez ve boruyu hava kilidiyle (emboli) işlevsiz bırakır; bu yüzden meşeler her bahar yaprak açmadan önce yeni bir dış trake halkası örmek zorundadır.'),
  ('İbreli ağaçların (çam, ladin, göknar) odunundaki trakeid hücrelerini birbirine bağlayan kenarlı geçitlerin ortasında yer alan \'torus-margo\' yapısı, komşu hücreye hava kabarcığı (emboli) girdiğinde nasıl hayat kurtarıcı bir işlev görür?', 'Basınç farkıyla esnek ağ üzerindeki kalın disk (torus) geçit ağzını emniyet valfi gibi kapatarak havanın yayılmasını durdurur', ['Hava kabarcığını kimyasal olarak parçalayıp oksijenini reçine asitlerine bağlayarak suya dönüştürür', 'Geçit kapaklarını tamamen eriterek komşu trakeidleri tek bir açık boru haline getirir', 'Köklerden kalsiyum karbonat çekerek hava dolu hücrenin içini mermer gibi taşlaştırır'], 'Trakeid geçitlerinde geçirgen \'margo\' lifleriyle asılı duran sızdırmaz \'torus\' yastıkçığı, bir trakeidde kavitasyon oluşup basınç düştüğünde sağlam hücre tarafına çekilip deliği mühürler ve su sütununun kopmasını sınırlar.'),
  ('Şarap ve viski yıllandırmada \'ak meşe\' (Quercus alba, Q. robur, Q. petraea) odunundan yapılan fıçıların sıvıyı hiç sızdırmazken, \'kırmızı meşe\' (Quercus rubra) odunundan yapılan fıçıların uçlarından sıvı kaçırmasının mikroskobik nedeni nedir?', 'Ak meşenin öz odunundaki geniş trake borularının komşu parankimalardan şişen \'tiloz\' kesecikleriyle tamamen tıkanmış olması', ['Kırmızı meşe odununda hiç lignin bulunmadığı için alkolle temas ettiğinde sünger gibi erimesi', 'Ak meşe ağacının gövdesinde hiç su borusu bulunmayıp yalnızca kapalı reçine kanallarının yer alması', 'Kırmızı meşenin yalnız baltalık sürgünü vermesi nedeniyle yıllık halkalarının arasında boşluk kalması'], 'Ak meşe grubunda diri odun öz oduna dönüşürken yan parankima hücreleri geçitlerden trake boşluğuna balon gibi şişerek (\'tylose / tiloz\') boruları tıkaç gibi kapatır; kırmızı meşede tiloz az olduğundan borular açık pipet gibi kalır.'),
  ('Yeryüzündeki en uzun ağaçların (sahil sekoyası, Douglas göknarı, dev okaliptüs - Eucalyptus regnans) zengin toprakta ve bol yağışta büyüseler dahi hiçbir zaman 125-130 metre boy sınırını aşamamasını açıklayan \'hidrolik sınırlama hipotezi\' neye dayanır?', 'Yerçekimi ve sürtünmeyle tepe yapraklarda su potansiyelinin aşırı düşüp hücre genişlemesini ve stoma açılışını durdurmasına', ['Yüz otuz metre yükseklikte atmosferdeki karbondioksit yoğunluğunun fotosenteze yetmeyecek kadar azalmasına', 'Köklerden tepeye çıkan şekerli floem öz suyunun doksan metreden sonra soğuktan donup kristalleşmesine', 'Çok uzayan ağaçların her fırtınada mutlaka yıldırım çekerek tepe meristeminin yanmasına'], 'Sekoyaların 110+ metredeki en üst sürgünlerinde su sütunu kavitasyon (kopma) sınırına dayanır; düşük turgor basıncı yüzünden en tepedeki yapraklar kurak çölde yaşıyormuş gibi küçük, kalın ve kseromorfik gelişir, boy uzaması durur.'),
  ('Göknar, ladin veya çam ormanında yıllar önce kesilmiş yapraksız bir ağaç kütüğünün hiçbir yeşil sürgünü olmadığı halde kesim yüzeyinde kambiyum ve kallus dokusu üreterek on yıllarca \'canlı kütük\' olarak kalabilmesi nasıl mümkündür?', 'Toprak altında komşu sağlıklı ağaçlarla kurduğu doğal kök kaynaşması (kök aşısı) ve mikorizal ağ üzerinden su ve karbon almasıyla', ['Kütüğün kahverengi mantar kabuğunun klorofil olmadan güneş ısısını doğrudan ATP ve glikoza çevirmesiyle', 'Kesilen kütüğün öz odununda elli yıl yetecek kadar sıvı sükroz ve nişasta depolanmış olmasıyla', 'Yağmur sularındaki çözünmüş organik asitlerin kesik yüzeyden emilerek hücre bölünmesini beslemesiyle'], 'Aynı türden komşu ağaçların kökleri toprakta birbirine bastığında kambiyumları birleşerek doğal kök aşılanması (inoskülasyon / root grafting) yapar; böylece kesilen bireyin kök sistemi komşu ağaçların ortak ağının parçası olarak beslenmeyi sürdürür.'),
  ('Yarı kurak orman ve savanlarda derin köklü bir meşe, akçaağaç veya akasya ağacının gece stomaları kapalıyken derin yer altı suyunu emip yüzeydeki kuru toprak katmanına kılcal köklerinden sızdırması (\'hidrolik kaldırma / hydraulic lift\') ekosistemi nasıl etkiler?', 'Gündüz kendi besin alımını kolaylaştırırken yüzeydeki sığ köklü otlara ve mikoriza mantarlarına da su paylaşımı sağlar', ['Yüzey toprağını tuzlu yer altı suyuyla boğarak çevredeki tüm otsu bitkilerin köklerini çürütür', 'Toprak sıcaklığını gece sıfırın altına düşürerek böcek larvalarının kışlamasını engeller', 'Kök basıncını tamamen sıfırlayarak ağacın ertesi sabah yapraklarını dökmesine yol açar'], 'Su potansiyeli farkıyla pasif olarak işleyen \'hidrolik yeniden dağıtım\' sayesinde derin köklü ağaçlar gece ıslattıkları üst topraktaki azot-fosfor mineralizasyonunu canlı tutar ve komşu sığ bitkilere kuraklık tamponu sağlar.'),
  ('Orman ağaçlarının kök ortaklıkları karşılaştırıldığında Kuzey kuşağının çam, kayın, meşe ve ladin ormanlarında \'ektomikoriza\' baskın iken, tropikal yağmur ormanlarındaki ağaçların büyük çoğunluğunda ve akçaağaç/dişbudakta hangi mikoriza tipi baskındır?', 'Mantar hiflerinin kök korteks hücre duvarını geçip dallı kesecikler kurduğu \'arbüsküler mikoriza (endomikoriza)\'', ['Yalnızca fundagillerde görülen ve turba proteinlerini parçalayan \'erikoid mikoriza\'', 'Yalnızca yeşil algler ile mantarların ağaç kabuğunda kurduğu \'epifitik liken birliği\'', 'Kök uçlarında leghemoglobin üreterek serbest azot bağlayan \'bakteriyel rizobyum nodülü\''], 'Glomeromycota mantarlarının kurduğu arbüsküler mikoriza (AM) kara bitkilerinin %80\'inde görülür ve hızlı mineral döngülü tropik ormanlarda baskındır; şapkalı mantarların kurduğu ektomikoriza ise organik azotun yavaş ayrıştığı serin-boreal ve ılıman kayın/çam ormanlarına üstünlük sağlar.'),
  ('Orta Asya\'nın kumlu çölleri olan Karakum ve Kızılkum\'da 4-6 metre boylanarak \'çöl ormanları\' kuran, yaprakları körelmiş yeşil sürgünlü ve çok sert yoğun odunu nedeniyle göçebelerin en değerli yakacağı olmuş bitki hangisidir?', 'Saksavul ağacı (Haloxylon ammodendron)', ['Yabani kuş iğdesi ağacı (Elaeagnus angustifolia)', 'Bodur dağ çamı çalısı (Pinus mugo)', 'Tüylü bozkır meşesi (Quercus pubescens)'], 'Horozibiğigiller (Amaranthaceae/Chenopodiaceae) familyasından saksavul, C4 fotosentezi yapan yeşil eklemli sürgünleri, 10 metreyi aşan kökleri ve suda batacak kadar ağır odunuyla Orta Asya kumullarını sabitleyen kilit çöl ağacıdır.'),
  ('Madagaskar\'ın güneyindeki kurak bölgede gelişen ve dünyadaki bitki türlerinin %90\'ından fazlası yalnız bu adaya endemik olan \'Madagaskar dikenli ormanı\'nda başrolü oynayan ağaçsı familya hangisidir?', 'Kaktüslere yakınsak evrimle benzeyen Didiereaceae (ahtapot ağaçları) ve şişe gövdeli baobablar', ['Kuzey Yarımküre kökenli kışın ibre döken melezler ve doğu ladini toplulukları', 'Batı Akdeniz kökenli mantar meşeleri ve yabani zeytin korulukları', 'Güney Amerika And Dağları\'na özgü kınakına ve Şili arokaryası ağaçları'], 'Madagaskar\'ın güneybatısındaki dikenli çalılık/orman biyomu, uzun gövdeleri diken ve küçük yapraklarla sarılı endemik Didiereaceae (Alluaudia procera vb.), ağaçsı sütleğenler ve 6 endemik Adansonia (baobab) türüyle benzersizdir.'),
  ('Ekvator üzerindeki yüksek tropikal dağların (Doğu Afrika\'da Kilimanjaro-Kenya Dağı ve Güney Amerika Andlar\'daki \'Páramo\' kuşağı) 3500-4300 metre yükseltilerinde \'her gece kış, her gündüz yaz\' yaşanan iklimde dev rozet bitkilerinin (Dendrosenecio, Espeletia) geliştirdiği sıra dışı uyum nedir?', 'Kurumuş eski yapraklarını gövde etrafında kalın yalıtım mantosu gibi tutmaları ve gece tomurcuklarını kapatıp don önleyici müsilaj salgılamaları', ['Yılın altı ayı yapraklarını tamamen döküp toprak altındaki soğanlarında kış uykusuna yatmaları', 'Gündüz kırk dereceye çıkan havada terlemeyi artırmak için dev delikli ince sucul yapraklar açmaları', 'Köklerinden tuzlu su pompalayarak tüm bitki yüzeyini buz tutmayan tuz kabuğuyla kaplamaları'], 'Tropikal alpin kuşakta mevsim farkı yoktur ama gündüz +15 °C olan sıcaklık her gece -5/-10 °C\'ye düşer; dev kanaryaotları (Dendrosenecio) ve Espeletia\'lar ölü yaprak kürküyle gövde suyunu donmaktan korur ve rozetlerini gece lahana gibi kapatır.'),
  ('Kanarya Adaları\'ndaki volkanik dağlarda yetişen \'Kanarya çamı\' (Pinus canariensis), çam cinsinin büyük çoğunluğunda görülmeyen hangi olağanüstü yangın uyumuyla kavrulmuş siyah gövdesinden yeniden yeşerebilir?', 'Kalın kabuk altında korunan uyur tomurcuklardan hem gövde boyunca hem kök boğazından gür sürgünler fışkırtabilmesiyle', ['Yanma anında iğne yapraklarından köpüklü karbondioksit salarak tepe alevlerini kendi kendine söndürmesiyle', 'Yangından hemen önce tüm reçinesini köklere indirip gövdesini yanmaz taş dokusuna çevirmesiyle', 'Yalnızca deniz suyunu emerek yapraklarında yangına dirençli kalın tuz tabakası biriktirmesiyle'], 'Kızılçam ve Halep çamı yangında genellikle ölür ve yalnız kozalak tohumlarıyla gençleşir; Kanarya çamı ve Kuzey Amerika\'daki Pinus rigida ise geniş yapraklılar gibi yanmış ana gövdeden epikormik sürgün vererek birey olarak hayatta kalabilen nadir çamlardır!'),
  ('Ege ve Batı Akdeniz kıyılarında, özellikle Dilek Yarımadası ve Gökova çevresindeki kireçtaşı kayalıklarda yetişen \'boz pırnal meşesi\' (Quercus aucheri), yaygın kermes meşesinden arazide nasıl ayırt edilir?', 'Yapraklarının alt yüzünün yoğun kısa yıldız tüyler nedeniyle grimsi-beyaz keçe gibi görünmesiyle', ['Yapraklarının yirmi santimetre uzunluğunda derin loblu olması ve her sonbaharda tamamen dökülmesiyle', 'Palamutlarının kanatlı samara şeklini alarak rüzgârla deniz üzerinden adalara uçmasıyla', 'Gövde kabuğunun huş ağacı gibi bembeyaz kağıt şeritler halinde soyulmasıyla'], 'Doğu Ege adaları ve Güneybatı Anadolu\'ya özgü dar yayılışlı bir Doğu Akdeniz elementi olan boz pırnal meşesi (Quercus aucheri), tüysüz parlak yeşil kermes meşesinden (Q. coccifera) yaprak altındaki boz-beyaz mumlu tüy örtüsüyle ayrılır.'),
  ('Adapazarı, Düzce, Zonguldak ve Artvin ile Adana-Gaziantep arasındaki sulak vadi tabanlarında yetişen, 40-50 santimetrelik sarkık salkımlar üzerinde kelebek kanatlı küçük cevizcikler taşıyan Tersiyer relikti ağacımız hangisidir?', 'Kanatlı ceviz / Yalankoz (Pterocarya fraxinifolia)', ['Anadolu sığla ağacı (Liquidambar orientalis)', 'Doğu çınarı ağacı (Platanus orientalis)', 'Sivri meyveli dişbudak (Fraxinus angustifolia)'], 'Cevizgiller (Juglandaceae) familyasından Kafkas kanatlı cevizi (yalankoz), su basar longoz ve dere kenarlarında hızlı büyüyen, tüysü bileşik yapraklı ve uzun salkımlar halindeki iki kanatlı fındıksı meyveleriyle çok gösterişli bir relikt türdür.'),
  ('Alplerde, Kuzey Amerika Kayalık Dağları\'nda ve Sibirya\'da yetişen \'fıstık çamları\' (örneğin Pinus cembra, Pinus albicaulis) yüksek dağ sınırında kanatsız ve iri yağlı tohumlara sahip oldukları halde rüzgârın tersine yamaç yukarı nasıl yayılırlar?', 'Göknar kargası (Nucifraga) kuşlarının boğaz kesesinde taşıdığı binlerce tohumu kar sınırı üstündeki sırtlara gömmesiyle', ['Kozalakların yamaç yukarı esen vadi meltemleriyle yuvarlanarak zirve kayalıklarına tırmanmasıyla', 'Dağ keçilerinin tohumları boynuzlarının arasına sıkıştırıp kayalara sürterek ekmesiyle', 'İlkbaharda eriyen çığ sularının ağır tohumları ters yönde dağ doruklarına çıkarmasıyla'], 'Çamların çoğu rüzgârla yayılan kanatlı tohum yaparken \'taş çamları\' (Strobus altcinsi) kanadını kaybetmiş ve göknar kargalarıyla (Nucifraga caryocatactes / columbiana) zorunluya yakın bir sinzookori kurmuştur; tek bir kuş yılda 30.000-100.000 tohum gömer ve uzamsal hafızasıyla çoğunu bulsa da kalanlar ağaç sınırını kurar.'),
  ('Afrika savanlarında yetişen şemsiye akasyalarının (Vachellia tortilis) kıvrık bakla meyveleri açılmadığı halde savan boyunca çok başarılı yayılması ve çimlenmesi büyük toynaklı otçullarla (antilop, zürafa, fil) nasıl bağlantılıdır?', 'Besleyici baklaları yiyen otçulların sindirim sıvısı tohum kabuğunu aşındırırken tohum içindeki tohum böceği larvalarını öldürür ve dışkıyla gübreli ortamda bırakır', ['Otçullar akasya baklalarını hiç yemez; yalnızca toynaklarıyla baklaları ezerek tohumların un haline gelmesini sağlar', 'Zürafalar baklaları ağızlarında çiğneyip akasya ağaçlarının en üst dal çatallarına tükürerek epifit çimlenme başlatır', 'Filler akasya ağaçlarını devirerek tohumların yalnız ana ağacın kök çukurunda üst üste çimlenmesine yol açar'], 'Yerde kalan akasya baklalarının içindeki tohumların %90\'ı Bruchid (tohum böceği) larvalarınca delinip yok edilir; antilop veya fil baklayı erken yuttuğunda mide asidi böcek yumurta/larvalarını öldürür, sert testayı yumuşatır ve tohumu ana ağaçtan uzağa gübre içinde eker.'),
  ('Güney Afrika\'nın Kap (Fynbos) bölgesinde yetişen \'Ceratocaryum argenteum\' adlı saz benzeri bitkinin kuru ve etsiz tohumlarının antilop dışkısına birebir benzeyen yuvarlak şekil, koyu kahverengi renk ve ağır dışkı kokusu salgılaması hangi hayvanı kandırarak yayılma sağlar?', 'Tohumu taze antilop dışkısı sanıp yuvarlayarak toprağın altına gömen bokböceklerini', ['Dışkı kokusuna gelen leş sineklerinin tohumu kanatlarına yapıştırıp uçurmasını', 'Antilopların kendi dışkılarını koklayıp tohumları yanlışlıkla tekrar yutmasını', 'Karıncaların dışkı topunu parçalayıp içinden tatlı nektar çıkarmaya çalışmasını'], 'Fekal mimikri (dışkı taklidi) olarak bilinen bu olağanüstü aldatmacada bitki elaiosom veya meyve eti üretmez; bokböceği uçucu koku bileşiklerine aldanıp sert tohumu yuvarlar ve ideal derinliğe gömdükten sonra yumurta bırakamadığını anlayıp terk eder!'),
  ('Doğu Karadeniz\'in Rize-Artvin yüksek dağ kuşağında yalnızca sınırlı lokalitelerde yetişen, yapraklarının alt yüzü kalın keçe tüylü ve çiçekleri pembe-erguvani renkli olan nadir ormangülü türümüz hangisidir?', 'Smirnov ormangülü (Rhododendron smirnowii)', ['Sarı çiçekli zifin komarı (Rhododendron luteum)', 'Akdeniz pembe zakkum çalısı (Nerium oleander)', 'Mor salkımlı adi leylak (Syringa vulgaris)'], 'Kolşik floranın en gösterişli nadir çalılarından olan Rhododendron smirnowii, 1500-2300 metreler arasındaki asidik kayalıklarda yetişir ve yaprak altındaki bej-beyaz yünsü tüy tabakasıyla mor komardan ayrılır.'),
  ('Trakya\'daki Istranca Dağları ile Batı ve Doğu Karadeniz\'in nemli vadi tabanlarında yetişen, uzun çiçek/meyve sapı ve çok sayıda paralel yan damarlı yapraklarıyla tanınan Karadeniz-Kolşik kökenli meşe türümüz hangisidir?', 'Istranca meşesi (Quercus hartwissiana)', ['Kurak yamaç tüylü meşesi (Quercus pubescens)', 'Ege bölgesi palamut meşesi (Quercus ithaburensis)', 'Akdeniz dikenli kermes meşesi (Quercus coccifera)'], 'Istranca meşesi nemli ve ılıman alüvyal ormanları seven Tersiyer kalıntısı bir meşe türü olup İğneada Longozu çevresinde ve Karadeniz vadilerinde diğer meşelerle karışık meşcereler oluşturur.'),
  ('Karadeniz\'deki yaygın adi şimşirden (Buxus sempervirens) daha iri derimsi yapraklara sahip olan ve Türkiye\'de yalnızca Antalya, Adana-Kozan ile Hatay\'ın sıcak kanyonlarında kopuk (disjunkt) yayılış gösteren şimşir türü hangisidir?', 'İspanyol şimşiri / Uzun yapraklı şimşir (Buxus balearica)', ['Herdemyeşil yabani karayemiş ağacı (Prunus laurocerasus)', 'Kırmızı gövdeli Akdeniz sandal ağacı (Arbutus andrachne)', 'Dikenli yapraklı Karadeniz çobanpüskülü (Ilex colchica)'], 'Buxus balearica bir uçta Batı Akdeniz\'de (Balear Adaları, İspanya, Fas), diğer uçta ise binlerce kilometre uzakta yalnız Güney Anadolu\'nun korunaklı vadilerinde kalmış çarpıcı bir Akdeniz reliktidir.'),
  ('Tropikal yağmur ormanlarında dev ağaçların tepelerine tırmanarak 150-200 metre uzunluğa erişebilen ve mobilya/sepet örücülüğünde kullanılan esnek \'rattan (hintkamışı)\', botanikte hangi bitki grubunun tırmanıcı üyesidir?', 'Palmiyegiller (Arecaceae) familyasının geriye kıvrık kancalı dikenlerle tırmanan sarmaşık palmiyesi', ['Buğdaygiller familyasının içi tamamen boş boğumlu yer altı rizomlu bambu kamışı', 'Söğütgiller familyasının nehir kıyılarında yetişen ince sürgünlü sepetçi söğüdü', 'Çamgiller familyasının tropikal kuşakta sarılıcı gövde kazanmış açık tohumlu türü'], 'Bambunun içi boş iken rattan (Calamus ve Daemonorops cinsleri) palmiyelerinin gövdesi boydan boya dolu, lifli ve çok esnektir; yaprak uçlarındaki kancalı kırbaçlarla (cirrus/flagellum) ağaç tepelerine tutunur.'),
  ('Orta Amerika ve Karayip nehir boylarında yetişen dev sarmaşık \'deniz fasulyesi / maymun merdiveni\' (Entada gigas), bir metreyi aşan baklalarından ayrılan kalp biçimli tohumlarıyla Atlantik Okyanusu\'nu aşıp Norveç ve İrlanda kıyılarına kadar canlı ulaşmasını neye borçludur?', 'Kalın su geçirmez tohum kabuğunun içinde çenekler arasında mühürlü kalan hava boşluğunun tohumu yıllarca yüzdürmesine', ['Tohumların göçmen deniz kuşlarının kursağında hiç sindirilmeden kıtalar arası uçurulmasına', 'Okyanus yüzeyinde yüzen dev deniz yosunu adalarının üzerinde çimlenerek ağaçlaşmasına', 'Tohum kabuğunun deniz suyundaki tuzu emip şişerek jelatinimsi bir balona dönüşmesine'], 'Golf Stream sıcak su akıntısının varlığını Avrupalı doğa bilimcilerin fark etmesine de katkıda bulunan \'deniz kalpleri\' (Entada gigas), taş gibi sert testası ve iç hava cebi sayesinde deniz suyunda 1-2 yıl canlı yüzebilir.'),
  ('Akdeniz\'deki kurak ve küçük kayalık adalarda memeli etçiller ve meyve kuşları az olduğunda \'Cneorum tricoccon\' veya \'kapari\' gibi çalıların hem çiçek tozlaşmasını hem de etli meyve yayılımını şaşırtıcı biçimde hangi omurgalı grup üstlenir?', 'Ada ekosisteminde yüksek yoğunluğa ulaşan ve beslenmesini nektar-meyveyle destekleyen duvar kertenkeleleri', ['Geceleri denizden karaya çıkıp çalılara tırmanan Akdeniz keşiş fokları', 'Kayalık yamaçlarda yalnız böcek avlayan zehirli boynuzlu engerek yılanları', 'Tatlı su birikintisi arayan kuyruksuz yeşil ağaç kurbağaları'], 'Anakarada tamamen böcekçil olan Podarcis cinsi Akdeniz kertenkeleleri, besin kıtlığı olan izole adalarda nektar ve sulu meyvelere yönelerek birçok ada bitkisinin ana tohum yayıcısı (saurokori) haline gelmiştir.'),
  ('Taşkıran (Chrysosplenium), kulakotu veya bazı adaçayı-mineçiçeği türlerinde olgun tohumların ucu açık küçük bir kadeh/çanak içinde bekletilip iri bir yağmur damlası çanağa çarptığında metrelerce uzağa fırlatılması hangi yayılma tipidir?', 'Yağmur damlası sıçratma enerjisini kullanan \'ombrohidrokori (sıçrama çanağı)\'', ['Meyvenin kendi turgor basıncıyla patlamasına dayanan \'otokorik fışkırtma\'', 'Kuruyan kapsül liflerinin bükülmesiyle işleyen \'higroskopik mancınık\'', 'Karıncaların yağlı besin cisimciğini taşıdığı \'mirmokokorik yayılma\''], 'Sıçrama çanağı (splash-cup) bitkilerinde çanak duvarının açısı (~40-50 derece) düşen yağmur damlasının kinetik enerjisini maksimum verimle dışarı yönlendirir ve tohumları damla hızının iki katıyla 1-2 metre uzağa fırlatır.'),
  ('Pıtrak (Xanthium strumarium) bitkisinin hayvan postuna yapışan dikenli meyvesinin içinde yan yana duran iki tohumdan alttaki büyük tohumun ilk ilkbaharda hemen çimlenmesi, üstteki küçük tohumun ise kabuğundaki kimyasal engel nedeniyle en az bir yıl daha uykuda beklemesi bitkiye ne kazandırır?', 'İlk yıl kuraklık veya don tüm fideleri öldürse bile ertesi yıl soyu sürdürecek \'evrimsel risk dağıtma (bahis koruma)\' güvencesi', ['Büyük tohumun erkek bitki, küçük tohumun ise bir yıl sonra onu dölleyecek dişi bitki olarak çıkmasını sağlama', 'Üstteki küçük tohumun hiç çimlenmeyerek alttaki fideye azot ve fosfor gübresi olarak erimesini sağlama', 'Hayvanın postunda kalan meyvenin ağırlığını her yıl yarı yarıya azaltarak rüzgârla uçmasını kolaylaştırma'], 'Somatik polimorfizm / heterokarpi adı verilen bu uyumda aynı ana bitki farklı çimlenme eşiklerine sahip tohumlar üretir; böylece belirsiz step ve tarla ortamlarında tek bir felaket tüm nesli silemez.'),
  ('Sık yapraklı bir kayın ormanının tabanına düşen \'öncü\' huş veya sığırkuyruğu tohumlarının toprağın tam yüzeyinde ve nemli ortamda bulundukları halde neden çimlenmeyip ağaç devrilene kadar beklediği nasıl açıklanır?', 'Üstteki yeşil yaprakların kırmızı ışığı emip aşağıya yalnız uzak-kırmızı ışığı (730 nm) sızdırarak fitokromu pasif Pr formunda kilitlemesiyle', ['Kayın yapraklarından damlayan yağmur suyunun tamamen oksijensiz saf suya dönüşmesiyle', 'Orman tabanındaki sıcaklığın yaz ortasında bile sıfır derecenin üzerine hiç çıkmamasıyla', 'Gölgedeki karıncaların tohum kabuğunu mumla sıvayarak su girişini engellemesiyle'], 'Yeşil klorofil fotosentez için kırmızı ışığı (~660 nm) soğurur, uzak-kırmızı ışığı (~730 nm) ise geçirir; orman tabanında düşen Kırmızı/Uzak-kırmızı (R/FR) oranı ışık seven tohuma \'üstün kapalı, çimlenirsen ışıksızlıktan ölürsün\' mesajı verir.'),
  ('İsrail\'deki Masada Kalesi kazılarında bulunan yaklaşık 2000 yıllık \'Yahudiye hurması\' (Phoenix dactylifera) çekirdeğinin çimlendirilip sağlıklı bir palmiyeye (\'Methuselah\') dönüştürülmesi ve Sibirya permafrostundan çıkarılan 32.000 yıllık \'Silene stenophylla\' meyvelerinden bitki üretilmesi tohum ömrü için hangi koşulların kritik olduğunu göstermiştir?', 'Çok düşük nem (kuruluk) veya dondurucu soğuk ile oksijen kısıtının metabolizmayı ve serbest radikal hasarını neredeyse durdurmasının', ['Tohumların canlı kalabilmesi için her on yılda bir mutlaka güneş ışığına çıkarılıp yıkanmasının', 'Yalnızca yüksek tuzlu deniz suyu içinde bekleyen tohumların binlerce yıl solunum yapabilmesinin', 'Büyük boyutlu ve yüksek su içerikli tropikal yağmur ormanı tohumlarının en uzun ömürlü olmasının'], '\'Ortodoks\' (kurumaya dayanıklı) tohumlar düşük nem ve serin/donmuş ortamda sitoplazmalarını camsı faza geçirerek yüzyıllarca canlı kalabilir; buna karşılık meşe, kestane ve kakao gibi \'rekalsitrant\' (kurumaya duyarlı) tohumlar kurursa birkaç haftada ölür.'),
  ('Meşe palamudu, at kestanesi, ceviz, avokado ve mango gibi ağaç tohumlarının buzdolabında kurutularak tohum bankalarında uzun yıllar saklanamayıp (\'rekalsitrant tohum\') kurutulduğunda hızla canlılığını yitirmesinin nedeni nedir?', 'Olgunlaştıklarında yüksek su içeriği ve aktif metabolizmayla dökülmeleri, kuruma sırasında hücre zarlarının geri dönüşsüz parçalanması', ['Tohum kabuklarının çelik kadar su geçirmez olması nedeniyle içeriye hiç oksijen girememesi', 'Bu tohumlarda embriyo ve çenek dokusunun hiç bulunmayıp yalnız spor kesesi yer alması', 'Kurutma sırasında tohum içindeki uçucu yağların tutuşarak embriyoyu yakması'], 'Standart tahıl ve çam tohumları (%5-10 neme kadar kuruyabilen ortodoks tohumlar) sıvı azotta asırlarca saklanabilir; ancak nemli ormanların iri \'rekalsitrant\' tohumları %20-30 nemin altına inerse ölür, bu yüzden yalnız canlı gen koruma bahçeleri veya kriyoprezervasyonla korunur.'),
  ('Anadolu\'da ve Akdeniz\'de ilkbahar sonunda açan \'yılanyastığı / danaayağı\' (Arum ve Dracunculus vulgaris) ile Endonezya\'nın dev \'titan arum\' (Amorphophallus titanum) çiçek kurullarının dış ortamdan 15-20 °C daha fazla ısınarak (yaklaşık 36-38 °C\'ye çıkarak) leş kokusu yaymasının fizyolojik mekanizması nedir?', 'Mitokondrilerdeki \'alternatif oksidaz\' yoluyla nişasta/yağ enerjisini ATP yerine doğrudan ısıya çevirip koku moleküllerini buharlaştırması', ['Koyu mor çiçek kılıfının öğle güneşini parabolik ayna gibi odaklayarak çiçeğin ortasını ısıtması', 'Çiçek içinde yaşayan çürükçül bakterilerin yoğun fermantasyon yaparak metan gazı yakması', 'Köklerin sıcak yer altı kaynak sularını çekip doğrudan çiçek ekseninden dışarı püskürtmesi'], 'Termojenik bitkiler (Araceae, bazı sikaslar ve nilüferler) memeli vücut sıcaklığına kadar ısınabilir; bu ısı hem çürük et kokulu dimetil disülfür bileşiklerini hızla havaya yayar hem de serin havada üşüyen tozlayıcı böceklere sıcak gece barınağı sunar.'),
  ('Orta Amerika\'nın \'boğa boynuzu akasyası\' (Vachellia cornigera) üzerinde yaşayan savunmacı \'Pseudomyrmex\' karıncaları, yalnızca böcek ve memeli otçulları ısırmakla kalmayıp konak ağaçlarına başka hangi kritik hizmeti verir?', 'Ağacın çevresinde filizlenen rakip bitkileri ve akasyaya sarılmaya çalışan yabancı sarmaşık uçlarını kemirip kurutarak ışık alanını temiz tutarlar', ['Toprağın altından kil tanecikleri taşıyarak akasya gövdesini yangına karşı çamurla sıvarlar', 'Geceleri ateşböceklerini yakalayıp çiçeklerin içine yerleştirerek tozlaşmayı aydınlatırlar', 'Kurak mevsimde kilometrelerce uzaktaki dereden ağızlarıyla su taşıyıp kök boğazını sularlar'], 'Akasya karıncalara içi boş diken yuvası, şekerli ekstrafloral nektar ve yaprakçık uçlarında yağ-proteince zengin \'Beltian cisimcikleri\' verir; karşılığında karıncalar hem 24 saat silahlı muhafızlık yapar hem de \'herbisit\' gibi çalışıp akasyaya değen tüm rakip sarmaşıkları biçer.'),
  ('Bir mısır, pamuk veya fasulye yaprağı mekanik olarak makasla kesildiğinde farklı, ancak bir tırtıl tarafından çiğnendiğinde tırtılın tükürüğündeki \'volisitin\' maddesini algılayarak çok özel uçucu organik bileşikler (\'HIPV\') salgılamasıyla ne amaçlanır?', 'Tırtılın doğal düşmanı olan parazitoit yaban arılarını kokusal \'yardım çığlığıyla\' yaprağa çağırmak ve komşu sağlam yapraklarda savunmayı önceden başlatmak', ['Tırtılın solunum borularını hoş çiçek kokusuyla tıkayarak bir dakika içinde boğulmasını sağlamak', 'Havadaki su buharını kesilen yaprak kenarında yoğunlaştırarak yarayı buzla kapatmak', 'Çevredeki otçul çekirge sürülerini aynı yaprağa çekerek tırtıllarla kavga ettirmek'], 'Dolaylı bitki savunmasının şaheseri olan bu mekanizmada bitki, tırtıl tükürüğündeki elisitörü tanır; salgıladığı terpenoid ve yeşil yaprak uçucularını izleyen parazitoit eşekarısı gelip yumurtalarını doğrudan tırtılın içine bırakarak bitkiyi kurtarır.'),
  ('Lahana, brokoli, turp, hardal ve roka gibi Turpgiller (Brassicaceae) bitkilerinin yaprağı bütün haldeyken keskin bir kokusu yokken, bir böcek veya insan tarafından çiğnendiği anda yakıcı \'hardal yağı\' (izotiyosiyanat) patlaması oluşması nasıl düzenlenmiştir?', 'Kükürtlü \'glukozinolat\' maddesi ile onu parçalayan \'mirosinaz\' enzimi ayrı hücre bölmelerinde tutulup yalnız doku ezildiğinde birleşecek şekilde depolanır', ['Çiğneme sırasındaki sürtünme ısısı yapraktaki selüloz liflerini yakarak kükürt dioksit gazı çıkarır', 'Bitki kökleri yaprak ısırıldığı anda topraktan saniyede on kat fazla sülfat çekip yaprağa pompalar', 'Tükürükteki amilaz enzimi yapraktaki klorofili parçalayarak acı kapsaisin molekülüne dönüştürür'], 'Biyolojide \'hardal yağı bombası\' (mustard oil bomb) denilen iki bileşenli kimyasal silahta substrat ve enzim sağlam dokuda birbirine değmez (yoksa bitki kendi kendini zehirler); hücreler tırtıl çenesiyle parçalandığında buluşup zehirli izotiyosiyanatları salar.'),
  ('İncir, sütleğen ve \'ipekotu\' (Asclepias) bitkileri yaprakları kesildiğinde basınçlı beyaz süt (\'lateks\') fışkırtarak küçük tırtılların ağız parçalarını zamk gibi yapıştırır. Buna karşın ünlü \'kral kelebeği\' (Danaus plexippus) tırtılı ipekotu yaprağını yemeden önce bu tuzağı nasıl etkisizleştirir?', 'Önce yaprağın ana damarını veya sapını kemirip keserek lateks kanal basıncını boşaltır, ardından sütü kesilmiş uç kısmı güvenle yer', ['Ağzından salgıladığı asetik asitle tüm beyaz sütü şekerli suya dönüştürerek içer', 'Yalnızca sonbaharda yere dökülüp tamamen kurumuş kahverengi ölü yapraklarla beslenir', 'Karıncalarla ortaklık kurup lateks damlalarını karıncalara temizlettikten sonra yaprağı yer'], 'Bitki-böcek silahlanma yarışının (birlikte evrim) en zarif örneklerindendir: Kral kelebeği tırtılı \'hendek kazma / damar kesme\' davranışıyla basınçlı lateksi devre dışı bırakır, ayrıca bitkideki zehirli kardiyak glikozitleri kendi vücudunda biriktirerek kuşlara karşı zehirli hale gelir!'),
  ('Buğdaygiller (çayır otları, bambu, kamış) ve at kuyrukları (Equisetum), topraktan emdikleri çözünür silisik asidi yaprak epidermisi içinde sert mikroskobik cam parçacıklarına (\'fitolit\') dönüştürür. Bu savunma otçul memelilerin evrimini nasıl yönlendirmiştir?', 'Zımpara gibi diş minesini aşındırdığı için at, sığır ve koyunlarda yüksek taçlı ve sert kıvrımlı öğütücü azı dişlerinin (hipsodonti) evrimleşmesine yol açmıştır', ['Otçul memelilerin tüm dişlerini kaybedip çimleri bütün yutan taşlıklı mideler geliştirmesine neden olmuştur', 'Çayır otlarının ateş aldığında cam tabakası sayesinde hiç yanmadan yeşil kalmasını sağlamıştır', 'Geviş getiren hayvanların çim yerine yalnızca ağaç kabuğu ve liken yemeye dönmesine sebep olmuştur'], 'Silika fitolitleri hem böcek çenelerini hem memeli dişlerini hızla köreltir; Miyosen döneminde C4-C3 çayır biyomları yayılırken otlayan atgiller ve boynuzlugiller bu aşınmaya karşı ömür boyu yükselen/dayanıklı yüksek taçlı (hipsodont) dişler geliştirmiştir.'),
  ('Şili ve Arjantin\'in ılıman yağmur ormanlarında yaşayan \'Boquila trifoliolata\' adlı odunsu sarmaşık, aynı bireyin uzanan sürgünü farklı ağaçlara tırmandığında bile tutunduğu her konak ağacın yaprak büyüklüğünü, şeklini, rengini ve sivri ucunu taklit etmesiyle nasıl bir rekor kırar?', 'Konak ağaca parazit bağlanmadığı halde uçucu kimyasallar veya mikrobiyal/optik ipuçlarıyla birden çok türü taklit edebilen \'polimorfik bukalemun bitki\' olmasıyla', ['Konak ağacın floem borularından çektiği mRNA ve kloroplastları doğrudan kendi yaprak hücrelerine yerleştirmesiyle', 'Yalnızca konak ağacın dökülen eski yapraklarını yapışkan sülükleriyle kendi çıplak dallarına yapıştırmasıyla', 'Üzerinde yaşayan tırtılların sarmaşık yapraklarını kemirerek konak ağacın yaprak şekline yontmasıyla'], '2014\'te Ernesto Gianoli ekibince keşfedilen Boquila trifoliolata, tek bir birey üzerinde bile üç farklı ağaca uzandığında üç farklı yaprak morfolojisi üretebilir; böylece zehirli/sert konak ağaçların kılığına girerek yaprak yiyen böceklerden gizlenir.'),
  ('Tatlı su göllerinin dibinde şerit yapraklarıyla yaşayan iki evcikli \'sazlık kurbağaotu / valisneriya\' (Vallisneria spiralis) bitkisi, polenlerini su altında ıslatmadan dişi çiçeğe ulaştırmak için nasıl akıl almaz bir su yüzeyi tozlaşması (\'epihidrofili\') gerçekleştirir?', 'Dişi çiçek uzun sarmal sapıyla su yüzüne çıkıp küçük bir çukur oluşturur; dipteki erkek çiçekler ise kopup minik yelkenli tekneler gibi su yüzünde yüzerek bu çukura kayar', ['Erkek bitki suyun içine şekerli bulut bırakarak küçük balıkların polenleri solungaçlarında taşımasını sağlar', 'Su seviyesi yazın tamamen çekilene kadar bekleyip rüzgârla tozlaştıktan sonra tekrar suya gömülür', 'Erkek çiçekler su altından uzun polen tüpleri uzatarak beş metre ötedeki dişi köklere bağlanır'], 'Vallisneria\'da su altında gelişen yüzlerce minik erkek çiçek tomurcuğu serbest kalıp hava kabarcığıyla su yüzeyine fırlar ve açılır; yüzey gerilimi sayesinde dişi çiçeğin yarattığı minik çöküntüye düşüp tozlaşır, ardından dişi sap tirbuşon gibi kıvrılıp meyveyi su altına çeker!'),
  ('Tarladaki genç ayçiçeği (Helianthus annuus) bitkilerinin sabah doğuya bakıp gün boyu güneşi batıya doğru izledikten sonra gece karanlıkta bile içsel saatle yeniden doğuya dönmesi, çiçek başı tamamen açılıp olgunlaşınca ise kalıcı olarak yalnız \'doğuya\' kilitlenmesinin yararı nedir?', 'Gençken gövdenin doğu-batı yüzlerindeki nöbetleşe oksin uzamasıyla büyümeyi artırmak, çiçek açılınca ise sabah güneşiyle hızla ısınıp tozlayıcı arıları beş kat fazla çekmek', ['Olgun çiçek başını batıdan gelen öğleden sonra yağmurlarından ve rüzgârlarından tamamen gizlemek', 'Tohumların yalnızca doğudan esen rüzgârlarla sökülüp tarlanın batı ucuna ekilmesini sağlamak', 'Öğleden sonra güneş ışığının sarı taç yapraklardaki karotenoidleri ağartmasını önlemek'], 'Genç ayçiçeğinde büyüme kaynaklı \'güneş izleme\' (diaheliotropizma) biyokütleyi %10-15 artırır; gövde uzaması durup çiçek açıldığında doğuya bakan tablalar sabah erken saatte hızla ısınır, üşüyen sabah arıları da sıcak doğu çiçeklerini seçer.'),
  ('Rüzgârdan tamamen yalıtılmış kapalı bir serada yetiştirilen genç ağaç fidanlarının açık araziye dikildiğinde ilk sert rüzgârda kolayca kırılıp yatması, buna karşılık rüzgârla sürekli sallanan fidanların daha kısa boylu, kalın gövdeli ve güçlü köklü büyümesi hangi olguyla açıklanır?', 'Mekanik sallanma ve temas stresinin etilen-kalsiyum sinyalleriyle boy uzamasını kısıp enine kalınlaşmayı uyardığı \'tigmomorfogenez\' ile', ['Sera camlarının morötesi ışığı geçirmemesi nedeniyle ağaçta hiç selüloz üretilememesi ile', 'Açık arazideki fidanların geceleri soğuktan donarak hücre duvarlarının taşlaşması ile', 'Rüzgârın yapraklardaki tüm oksini uçurarak tepe tomurcuğunu kalıcı olarak öldürmesi ile'], 'Ünlü \'Biyosfer 2\' kapalı kubbe deneyinde rüzgâr olmadığı için ağaçlar hızla boylanıp kendi ağırlıkları altında devrilince bu olgunun önemi çarpıcı biçimde anlaşılmıştır; rüzgâr salınımı (tigmomorfogenez) ağaçların sağlam reaksiyon ve destek odunu örmesi için zorunlu mekanik uyarıdır.'),
  ('Kuzeydeki Sarıkamış sarıçamları veya Sibirya huş ağaçları kışın -40 °C soğuğa dayanabilirken, aynı ağacın temmuz ortasında aniden -5 °C sıcaklığa maruz bırakıldığında ölmesi ve sonbaharda adım adım kazandığı \'soğuk sertleşmesi (aklimasyon)\' hücresel düzeyde nasıl sağlanır?', 'Hücre zarında doymamış yağ asitleri artırılarak akışkanlık korunur; sitoplazmada şeker/antifriz proteinleri yoğunlaştırılıp buz kristallerinin yalnız hücre dışı boşluklarda oluşması sağlanır', ['Sonbaharda ağacın köklerinden gövdesine kadar tüm su tamamen boşaltılarak sıfır nemli kuru odun haline geçilir', 'Kış başında hücre duvarları kalın bir mum tabakasıyla kaplanarak içerideki sıcaklığın artı on derecede kalması sağlanır', 'Mitokondriler kış boyunca kesintisiz yakıt yakarak her bir ibrenin sıcaklığını donma noktasının üstünde tutar'], 'Canlı bitki hücresinin *içinde* sivri buz kristali oluşursa zarlar yırtılır ve hücre anında ölür; soğuğa alışmış ağaçlar sitoplazma yoğunluğunu artırıp kontrollü su çıkışıyla buzlanmayı yalnız zararsız \'hücreler arası boşluklara\' hapseder ve zar esnekliğini lipit değişimiyle korur.'),
  ('Mısır, şekerkamışı, sorgum ve sıcak savan çayırlarındaki birçok buğdaygil ile saksavul gibi kurakçıl bitkilerin kavurucu sıcak ve parlak ışıkta standart \'C3\' ağaçlarına göre çok daha az su harcayarak yüksek hızda fotosentez yapmasını sağlayan \'C4 yolu\' nasıl çalışır?', 'PEP karboksilaz enzimiyle CO₂\'yi önce 4 karbonlu aside bağlayıp demet kını hücrelerindeki Rubisco çevresine pompalayarak israflı \'fotorespirasyonu\' ortadan kaldırır', ['Stomalarını gündüz tamamen kapatıp yalnızca gece yarısı ay ışığında karbondioksit emerek nişasta depolar', 'Klorofil yerine kırmızı karotenoid pigmentleri kullanarak kızılötesi ısı ışınlarından doğrudan şeker sentezler', 'Suyu parçalamadan doğrudan topraktaki organik humustan hidrojen ve karbon çekerek oksijen salımını durdurur'], 'Sıcak havalarda standart C3 bitkilerinde stomalar kısılınca Rubisco enzimi CO₂ yerine O₂ bağlayarak enerji harcayan \'fotorespirasyon\' hatasına düşer; C4 bitkileri \'Kranz (çelenk) anatomisi\' ve PEP karboksilaz ön pompasıyla yarı kapalı stomalarda bile Rubisco\'yu saf CO₂ ile doyurur.'),
  ('Ev ve iş yerlerinde büyük parlak derimsi yapraklarıyla yetiştirilen \'salon kauçuğu\' (Ficus elastica) yaprağının enine kesiti mikroskopta incelendiğinde kurakçıl/epifitik geçmişini yansıtan hangi karakteristik yapılar bir arada görülür?', 'Üst yüzde çok katlı epidermis (su depolayıcı), alt yüzde çukurda gömülü stomalar ve salkım biçimli kalsiyum karbonat kristali', ['Tek sıra ince kütikulasız epidermis, yalnızca üst yüzde açık stomalar ve geniş aerenkima hava kanalları', 'İğne yapraklarda olduğu gibi reçine kanalları, endodermis halkası ve transfusyon iletim dokusu', 'Kranz tipi çelenk demet kını kloroplastları ile üst yüzde büzülen motor bülliform hücreler'], 'Ficus elastica doğada hayata ağaç dalında epifit (su kıtlığı çeken boğucu incir) olarak başladığından çok katlı üst epidermis, kalın kütikula, stomatik kripta (tüylü stoma çukuru) ve ışığı iç dokulara dağıtan üzüm salkımı görünümlü \'sistolit\' taşıyla kseromorfik anatomi ders örneğidir.'),
  ('Tropikal gelgit kıyılarında doğrudan deniz suyunun (%3,5 tuzlu) içinde köklenen \'kırmızı mangrov\' (Rhizophora mangle), yapraklarında tuz salgı bezleri bulunmadığı halde öz suyunu neredeyse tatlı su düzeyinde nasıl tutar?', 'Kök endodermisindeki süberinli Caspary şeridi ve hücre zarlarında negatif basınçla işleyen \'ters osmoz benzeri ultrafiltrasyonla\' tuzun %90-99\'unu daha köke girerken dışlayarak', ['Deniz suyunu hiç emmeyip yalnızca gelgit çekildiğinde havadan yağmur suyunu gövde kabuğuyla toplayarak', 'Köklerindeki simbiyotik bakterilere sodyum klorürü tükettirip zararsız azot gazına çevirterek', 'Aldığı tüm tuzu her akşam çiçek nektarıyla dışarı atıp yengeçlere yedirerek'], 'Halofit mangrovlar iki ana gruba ayrılır: Avicennia ve Aegiceras tuzu kısmen alıp yaprak tuz bezlerinden dışarı terlerken (\'tuz salgılayıcılar\'), Rhizophora ve Bruguiera üç katlı kök bariyeriyle tuzu daha kapıda filtreler (\'tuz dışlayıcılar\') ve kalan az tuzu da sararıp dökülecek yaşlı \'kurban yapraklara\' yükler.'),
  ('Anadolu yaylalarında ve nemli yol kenarlarında yazın iki metre boylanan dev şemsiye çiçekli \'dev tavşancıl otu\' (Heracleum mantegazzianum / platytaenium) veya sedefotu bitkisinin öz suyu cilde bulaştıktan sonra güneşe çıkıldığında ikinci derece su toplamalı yanıklar oluşmasının (\'fitofotodermatit\') nedeni nedir?', 'Bitki öz suyundaki \'furanokumarin\' bileşiklerinin deri hücrelerine sızıp güneşin UV-A ışınlarıyla uyarıldığında DNA ve hücre zarlarını yakması', ['Bitkinin gövde içi boşluğunda yüksek derişimde sülfürik asit ve nitrik asit biriktirmesi', 'Öz suyundaki şeffaf reçinenin deri üzerinde büyüteç merceği oluşturarak güneşi odaklaması', 'Bitki tüylerinin taşıdığı parazitik mantar sporlarının sıcak havada deride çoğalması'], 'Maydanozgiller (Apiaceae) ve Turunçgillerin bazı üyelerindeki furanokumarinler karanlıkta zararsız görünür; ancak cilde değdikten sonra güneşin morötesi (UV-A) ışığıyla fototoksik tepkimeye girerek ağır kimyasal yanıklara ve aylarca süren lekelere yol açar.'),
  ('Danimarkalı botanikçi Christen Raunkiær\'in dünya bitkilerini elverişsiz mevsimi (sert kışı veya kurak yazı) geçiren \'yenilenme tomurcuklarının yerden yüksekliğine\' göre sınıflandırdığı yaşam formu sisteminde bütün ağaç ve boylu çalılar hangi gruba girer?', 'Tomurcukları yerden yirmi beş-elli santimetreden yüksekte havada açıkta kışlayan \'fanerofitler\'', ['Tomurcuklarını tamamen toprağın altındaki soğan ve yumrularda gizleyen \'kriptofitler (geofitler)\'', 'Kışı yalnızca tohum halinde geçirip ana bitkisi tamamen ölen tek yıllık \'terofitler\'', 'Tomurcukları tam toprak yüzeyinde ölü yaprak ve kar altında korunan \'hemikriptofitler\''], 'Raunkiær yaşam formları iklim-bitki uyumunu özetler: Tropik ve ılıman ormanlarda \'fanerofitler\' (ağaç/çalı), otlak ve bozkırlarda \'hemikriptofitler\', çöllerde \'terofitler\' (tek yıllıklar) ve Akdeniz/step geçişlerinde soğanlı \'kriptofitler\' oranını artırır.'),
  ('Güney Afrika ve Namibya\'nın kavurucu Namib Çölü kenarlarında yetişen ağaçsı aloe türü \'ok kılıfı ağacı\' (Aloidendron dichotomum), iklim ısınması ve kuraklık şiddetlendiğinde aşırı su kaybından kurtulmak için hangi radikal öz-budama uyumunu sergiler?', 'En uçtaki bazı yaprak rozetlerini ve yan dallarını bilerek kurutup ayrılma dokusundan atarak (\'kladoptoz\') su tüketen taç yüzeyini küçültür', ['Tüm gövdesini toprağın altına çekip on yıl boyunca yalnızca yer altı yumrusu olarak bekler', 'Yapraklarını eriterek gövdesinin çevresine şeffaf bir cam serası kabuğu örer', 'Köklerini koparıp çöl rüzgârıyla daha yağışlı dağ eteklerine doğru yuvarlanarak göç eder'], 'Yerli San halkının içi süngerimsi dallarını oyup ok kılıfı (quiver) yaptığı bu sukulent ağaç, beyaz tozlu (güneş yansıtıcı) gövde kabuğuna sahiptir ve kuraklık uzadığında uç dallarını mühürleyip feda ederek ana gövdedeki suyu korur.'),
  ('Karadeniz Bölgesi\'nin kireçli kayalıklarında, Rize-Artvin ve Kastamonu kanyonlarında tutunan \'Doğu gürgeni / İnce yapraklı gürgen\' (Carpinus orientalis), boylu adi gürgenden (Carpinus betulus) morfolojik ve ekolojik olarak nasıl ayrılır?', 'Daha kurak-taşlık yamaçlarda çalı veya küçük ağaç kalması ve meyve salkımındaki uçma yapraklarının (brakte) üç loblu değil tek parça dişli olmasıyla', ['Kış aylarında yapraklarını hiç dökmeyip dikenli herdemyeşil maki yaprakları taşımasıyla', 'Kırk metre boya ulaşıp yalnızca su altındaki longoz bataklıklarında yetişmesiyle', 'Meyvelerinin odunsu kozalak pulları arasında kanatlı çıplak tohumlar halinde gelişmesiyle'], 'Adi gürgen derin nemli orman topraklarında 25 m boylanır ve meyve braktesi belirgin üç lobludur; Doğu gürgeni (Carpinus orientalis) ise daha küçük yapraklı, kurak kalker yamaçlara dayanıklı ve tek parçalı üçgenimsi testere dişli braktelidir.'),
  ('Avrupa\'nın alçak rakımlı ılıman ormanlarında (ve Trakya-Marmara\'da) yayılış gösteren iki temel meşe türü olan \'saplı meşe\' (Quercus robur) ile \'sapsız meşe\' (Quercus petraea) arazide yaprak sapı ve palamut sapı karşılaştırılarak nasıl ayırt edilir?', 'Saplı meşede yaprak çok kısa saplı fakat palamut uzun bir sap ucunda asılı iken; sapsız meşede yaprak uzun saplı fakat palamut dala sapsız oturur', ['Saplı meşede hem yaprak hem palamut on santimetre saplı iken; sapsız meşede her ikisi de tamamen sapsızdır', 'Saplı meşe dört mevsim yeşil dikenli yapraklı iken; sapsız meşe iğne yapraklı ve iki yılda olgunlaşan kozalaklıdır', 'Sapsız meşenin palamutları kanatlı samara biçiminde iken; saplı meşenin palamutları etli kırmızı kabukludur'], 'Öğrencileri en çok şaşırtan ters isimlendirmedir! \'Saplı meşe\' (pedunculate oak) adını *meyve (palamut) sapının* uzunluğundan alır (yaprağı neredeyse sapsız ve kulakçıklıdır); \'sapsız meşe\' (sessile oak) ise sapsız oturan palamutlara ama belirgin uzun yaprak saplarına sahiptir.'),
  ('Yüksek dağ orman sınırında veya rüzgârlı kutup altı kıyılarda ladin ve göknar ağaçlarının alt dallarının kar ağırlığıyla toprağa değip yosun içinde kök salması, böylece ana gövde çevresinde halka şeklinde yavru klon ağaççıklar (\'etek dallanması / layering\') oluşturması ne sağlar?', 'Yaz soğuğunda tohum olgunlaştırmanın başarısız olduğu ekstrem sınırda eşeysiz klonal çoğalmayla bireyin binlerce yıl aynı noktada tutunmasını', ['Alt dalların topraktaki tüm suyu emerek ana gövdeyi bilerek kurutup öldürmesini', 'Tohumların rüzgârla uçmak yerine yalnızca yer altındaki solucan tünelleriyle yayılmasını', 'Ağacın her kış mevsiminde köklerini söküp daha kuytu vadi tabanına kaymasını'], 'İsveç\'teki Dalarnas Dağları\'nda bulunan ve kök sistemi 9.550 yaşında olduğu radyokarbonla belirlenen ünlü \'Old Tjikko\' Norveç ladini, binlerce yıl boyunca tam da bu doğal daldırma (layering) klonlamasıyla gövdesini yenileyerek hayatta kalmıştır!'),
  ('Buğday veya arpa tarlasında hasat mevsimi tam yaklaşmışken birkaç gün süren ılık ve sürekli yağmurlu hava sonucunda tanelerin henüz başak üzerindeyken kökçük çıkarıp çimlenmesi (\'başakta çimlenme\') tohumdaki hangi hormon eksikliğiyle ilişkilidir?', 'Tohum uyku halini (dormansiyi) koruyan \'absisik asit (ABA)\' düzeyinin düşüp nişastayı parçalayan \'giberellin (GA)\' etkisinin baskın çıkmasıyla', ['Meyve olgunlaştıran etilen gazının başaklarda tamamen tükenip sitokinin hormonunun sıfırlanmasıyla', 'Kök uçlarından başağa aşırı miktarda büyüme engelleyici salisilik asit taşınmasıyla', 'Yağmur suyundaki azotun tohum kabuğundaki lignini anında eritip yok etmesiyle'], 'İnsan seçilimiyle kültür tahıllarında hızlı ve eşzamanlı çimlenme istendiği için yabani atalarındaki güçlü ABA dormansisi zayıflatılmıştır; bunun yan etkisi olarak hasat öncesi yağışta ABA/GA oranı düşerse α-amilaz nişastayı parçalayıp un kalitesini bozan başakta çimlenmeye (vivipari benzeri duruma) yol açar.'),
  ('Aynı maki kuşağında sıklıkla yabani zeytin (delice) veya kermes meşesiyle karıştırılan, karşılıklı dizilişli koyu yeşil derimsi yapraklara ve küçük mavi-siyah zeytinimsi meyvelere sahip olan Zeytingiller üyesi çalı/ağaççık hangisidir?', 'Akçakesme (Phillyrea latifolia)', ['Akdeniz defnesi (Laurus nobilis)', 'Tespih çalısı (Styrax officinalis)', 'Hayıt çalısı (Vitex agnus-castus)'], 'Akçakesme yapraklarının alt yüzü zeytindeki gibi gümüşi beyaz değil açık yeşildir; kermes meşesinden ise yapraklarının dal üzerinde \'karşılıklı (opozit)\' dizilmesiyle (meşede almaşık dizilir!) sahada hatasız ayırt edilir.'),
  ('Bir orman ekosisteminde atmosferden fotosentezle tutulan toplam karbon miktarından (Brüt Birincil Üretim), ağaçların kendi yaşamlarını sürdürmek için yaptığı solunum ve toprak canlılarının (mantar/bakteri) ayrıştırma solunumu çıkarıldığında geriye kalan \'Net Ekosistem Üretimi\' 500 yaşındaki çok yaşlı bakir bir ormanda ne durumdadır?', 'Sıfıra yakın dengeli ya da ılımlı pozitif durumdadır; dev biyokütle ve toprakta muazzam bir karbon stoğu tutmayı sürdürür', ['Yaşlı ağaçlar fotosentezi tamamen bıraktığı için her yıl tüm karbon stoğunu atmosfere geri verir', 'Genç bir tarladan yüz kat daha hızlı yeni odun biriktirerek her yıl boyunu ikiye katlar', 'Toprakta hiç ayrıştırıcı mantar yaşamadığı için dökülen yaprakların tamamı elmasa dönüşür'], 'Klasik Odum kuramı yaşlı (klimaks) ormanların karbon dengesinin tam sıfır olduğunu varsaymışsa da modern kule ölçümleri yaşlı ormanların bile toprak humusu ve yeni fidanlarla net karbon yutağı olabildiğini, en önemlisi kesildiğinde atmosfere salınacak devasa bir \'karbon kasasını\' kilitli tuttuğunu kanıtlamıştır.'),
  ('Brezilya\'nın Amazon yağmur ormanlarından dünyaya yayılan \'Brezilya fıstığı\' dışında, yapraklarının alt yüzü bembeyaz olduğu için rüzgârda gümüş gibi parlayan ve içi boş boğumlu gövdesinde \'Azteca\' karıncalarını barındıran hızlı büyüyen neotropikal öncü ağaç hangisidir?', 'Boru ağacı / Tembel hayvan ağacı (Cecropia)', ['Güney Amerika maun ağacı (Swietenia macrophylla)', 'Amazon kauçuk ağacı (Hevea brasiliensis)', 'And kınakına ağacı (Cinchona pubescens)'], 'Isırgangillerle akraba Cecropia ağaçları yağmur ormanında açılan her ışık boşluğunda hızla yükselir; bambu gibi bölmeli içi boş gövdesinde yaşayan Azteca karıncalarını yaprak sapı tabanındaki glikojence zengin \'Müller cisimcikleriyle\' besleyip savunma hizmeti alır.'),
  ('Tarlalarda mısır, darı ve sorgum köklerine yer altından bağlanarak konak bitki daha toprak üstüne bile çıkmadan tüm gücünü sömüren, Sahra Altı Afrika\'da milyonlarca hektar tahıl kaybına yol açan \'cadı otu\' (Striga) tohumları konak kökün yanına geldiğini nasıl anlar?', 'Konak bitki kökünün mikoriza mantarlarını çağırmak için toprağa çok düşük derişimde salgıladığı \'strigolakton\' hormonunu algılayıp yalnız o zaman çimlenerek', ['Mısır köklerinin büyüme sırasında taşlara sürtünerek çıkardığı akustik ses dalgalarını dinleyerek', 'Toprak sıcaklığının mısır gölgesi sayesinde beş derece düşmesini termal sensörlerle ölçerek', 'Yalnızca mısır çiçeklerinden dökülen sarı polenlerin yağmurla toprağa sızmasını bekleyerek'], 'Evrimsel casusluğun zirvesidir: Bitkiler fosfor kıtlığında faydalı mikoriza mantarlarına \'buradayım, gel bağlan\' demek için topraktan \'strigolakton\' salgılar; toz küçüklüğündeki parazit Striga ve canavar otu (Orobanche) tohumları da bu gizli şifreyi dinleyip tam kök dibinde uyanır!'),
  ('Güneydoğu Asya\'nın turba bataklığı ve alçak ova yağmur ormanlarına (Borneo, Sumatra, Malezya) egemen olan, iki (veya beş) uzun çanak yaprak kanadıyla helikopter gibi dönen meyveler üreten ve birkaç yılda bir tüm familya üyeleriyle eşzamanlı \'genel çiçeklenme\' yapan dev ağaç familyası hangisidir?', 'İki kanatlı meyveliler / Dipterocarpaceae', ['Kayıngiller / Fagaceae', 'Çamgiller / Pinaceae', 'Söğütgiller / Salicaceae'], 'Güney Amerika ve Afrika yağmur ormanlarından farklı olarak Güneydoğu Asya kanopisine 70-80 metrelik \'Dipterocarpaceae\' (Shorea, Dipterocarpus - sarı meranti vb.) ağaçları hakimdir; El Niño kuraklık düşüşü sinyaliyle 3-7 yılda bir tüm orman aynı anda çiçek açıp avcı doygunluğu yaratır.'),
  ('Kuzey Anadolu ve Kafkasya\'nın nemli kayın ormanları altında şubat-mart aylarında kar kalkarken parlak sarı-yeşil çiçek kümeleri açan, ancak kabuğu ve kırmızı meyveleri \'mezerein\' toksini nedeniyle çok zehirli olan bodur orman çalısı hangisidir?', 'Sırımbağı / Kurtbağrı değil \'Dulaptalotu / Defne çalısı\' (Daphne pontica ve Daphne mezereum)', ['Yenilebilir ayıüzümü likapa çalısı (Vaccinium arctostaphylos)', 'Şifalı kuşburnu yabani gül çalısı (Rosa canina)', 'Kokulu çiçekli adi ıhlamur fidanı (Tilia rubra)'], 'Thymelaeaceae familyasından Daphne türleri (Karadeniz\'de D. pontica, yükseklerde D. oleoides ve D. mezereum) lifli ve kopmayan esnek kabukları nedeniyle \'sırımbağı\' adını alır; meyveleri memeliler için çok zehirli iken ardıç kuşları etkilenmeden tohumlarını yayar.'),
  ('Bir göl tabanından alınan 15 bin yıllık tortul karotta en alt katmanda pelin otu (Artemisia) ve kazayağıgiller polenleri baskın iken, üst katmanlara çıkıldıkça sırasıyla huş-çam, ardından meşe-fındık ve en üstte kayın-gürgen polenlerinin baskınlaşması iklim ve orman tarihi açısından ne anlatır?', 'Son buzul çağının soğuk-kurak bozkırından ılımanlaşmayla önce öncü ormanlara, sonunda da nemli-serin kapalı klimaks ormana geçildiğini', ['Bölgenin başlangıçta tropikal yağmur ormanı iken giderek kuruyarak mutlak çöle dönüştüğünü', 'Göl suyunun tuzluluk oranının artarak tatlı su bitkilerinden mangrov ormanlarına geçildiğini', 'Rüzgârla tozlaşan tüm ağaçların yok olup yerini yalnızca böcekle tozlaşan otlara bıraktığını'], 'Palinolojik polen diyagramları Avrupa ve Kuzey Anadolu\'nun Holosen (son 11.700 yıl) orman öyküsünü böyle belgeler: Buzul çekilirken soğuk step (Artemisia) yerini hızlı yayılan öncü huş ve sarıçama, ısınma ve nemlenmeyle de meşe, fındık ve gölge ağacı kayına bırakmıştır.'),
  ('Güneydoğu Anadolu ve Doğu Akdeniz\'de doğal yetişen \'harnup / keçiboynuzu\' (Ceratonia siliqua) ağacında sonbaharda açan küçük yeşilimsi-kırmızımsı çiçeklerin kalın odunsu dallar üzerinde doğrudan kümeleşmesi (kauliflori) dışında üreme biyolojisinde hangi özellik dikkat çeker?', 'Çoğunlukla iki evcikli (erkek ve dişi ağaçları ayrı) olup sonbaharda hem rüzgâr hem de ekşimsi kokuya gelen sinek/arılarla tozlaşması ve baklasının tam bir yılda olgunlaşması', ['İlkbahar başında iri beyaz taç yapraklar açıp yalnızca gece güveleriyle tozlaştıktan on gün sonra meyve dökmesi', 'Açık tohumlu bir ağaç olduğu için çiçek açmayıp kozalak pulları arasında kanatlı tohum geliştirmesi', 'Yalnızca kök sürgünleriyle eşeysiz çoğaldığı için doğada hiçbir zaman çiçek ve tohum oluşturmaması'], 'Keçiboynuzu Akdeniz\'de sonbaharda (eylül-kasım) çiçek açan nadir ağaçlardandır; taç yapraksız çiçekleri kendine özgü ağır bir koku yayarak sinek, eşekarısı ve arıları çeker, döllenen bakla ertesi yılın sonbaharında karamelize-tatlı meyveye dönüşür.'),
  ('Orta Avrupa, Balkanlar ve Kuzey Anadolu\'nun meşe-gürgen ormanlarında meşe ve elma dallarında sarımtrak-yeşil çalılar kuran \'ökseotu\'nun (Viscum album) yanında, yalnız meşe türleri üzerinde yaşayan ve kışın yapraklarını döküp altın sarısı üzümsü meyveler veren diğer yarı parazit akrabası hangisidir?', 'Meşe ökseotu / Sarı ökseotu (Loranthus europaeus)', ['Klorofilsiz kırmızı cinsaçı (Cuscuta campestris)', 'Toprak altı mor canavar otu (Orobanche ramosa)', 'Herdemyeşil duvar sarmaşığı (Hedera helix)'], 'Adi ökseotu (Viscum album) kışın yeşil kalıp beyaz meyve verir ve çam, göknar, armut, kavak üzerinde yaşar; Loranthus europaeus ise gerçek meşe ve kestaneler üzerinde yaşar, sonbaharda yaprak döker ve kışın çıplak dalda sarı meyveleriyle tanınır.'),
];
